// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_6: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.stinking-cloud","name":"Stinking Cloud","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a cloud of putrid mist in the area. The cloud functions as except it sickens creatures that end their turns within the cloud. (The condition is not a poison effect.)\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Sickened 1.\n\nFailure The creature is Sickened 1 and Slowed 1 while in the cloud.\n\nCritical Failure The creature is Sickened 2 and Slowed 1 until it leaves the cloud.","source":{"provider":"PAIZO","sourceId":"GKpEcy9WId6NJvtx","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.stone-lance","name":"Stone Lance","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["attack","concentrate","earth","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"6d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You conjure a jagged lance of stone and then launch it at a foe. Make a spell attack roll against the target. On a hit, you deal 6d6 piercing damage and the lance impales the creature, giving it a –10-foot circumstance penalty to its Speeds unless it Escapes. On a critical hit, if the creature is on the ground, the lance also embeds into the ground and Immobilizes the creature until it Escapes. A creature that Escapes after being impaled takes 3[bleed] damage. When the spell ends, the lance crumbles into dirt, freeing the target if it hasn't Escaped.\n\nHeightened (+1) Increase the damage by 2d6 and the persistent bleed damage for Escapes by 1.","source":{"provider":"PAIZO","sourceId":"ECApRjIIxD0JogOa","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.strength-of-mind","name":"Strength of Mind","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","mental"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bolster your ally with reminders of their physical prowess, granting them additional defenses against harmful mental effects. The target gains a +1 status bonus to saving throws against mental effects and against effects that hinder movement (including those that reduce Speed or apply the , , or conditions). This bonus increases to +2 if the source of the effect has the fear trait.","source":{"provider":"PAIZO","sourceId":"aMvjaIuPIWN7pbc3","book":"Pathfinder #209: Destroyer's Doom","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.subjugate-undead","name":"Subjugate Undead","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"one undead creature with a level of no more than your level -4","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You attempt to seize control of the target. It can attempt a Will save to resist the effect. If the target is already being controlled by another creature, the controlling creature also rolls a saving throw and the undead uses the better result. Casting subjugate undead again ends any previous subjugate undead you cast.\n\nCritical Success The target is unaffected and is temporarily immune for 24 hours.\n\nSuccess The target is unaffected.\n\nFailure The undead creature becomes a minion under your control for 1 minute. The spell is dismissed if you or an ally takes a hostile action against the minion undead.\n\nCritical Failure As failure, except the duration is 10 minutes.","source":{"provider":"PAIZO","sourceId":"Cd6Crl4wpQaMSYrF","book":"Pathfinder Book of the Dead","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sudden-recollection","name":"Sudden Recollection","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You place a bit of knowledge deep in a creature's subconscious or make a willing creature forget some information until a specific trigger occurs. The target gets a Will saving throw to resist the effect. A willing creature can choose to fail its save.\n\nCritical Success The target is unaffected and realizes you tried to alter its memory.\n\nSuccess The target is unaffected but thinks your spell was something harmless instead of sudden recollection, unless it identifies the spell.\n\nFailure You choose a piece of information the target didn't already know and create a trigger, such as seeing an object, hearing a key phrase, or witnessing an event. As soon as the target experiences the trigger, it receives the information and the spell ends. If the target was willing, you can instead choose a piece of information the target already knew and suppress its memory of that information until it experiences the trigger, after which it recovers the information and the spell ends.","source":{"provider":"PAIZO","sourceId":"h5cMTygLpjY3IEF0","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.suns-fury","name":"Sun's Fury","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 weapon without an unholy rune that is unattended or wielded by you or a willing ally","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target weapon becomes wreathed in a glowing flame. The weapon deals an additional 1d4 fire and 1 spirit damage on a successful Strike. In addition, the flame causes the weapon to glow as bright as a torch. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"LrFUj76CHDBV0vHW","book":"Pathfinder Lost Omens Legends","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.swamp-of-sloth","name":"Swamp of Sloth","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","olfactory","sorcerer"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"1d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"Ground in the area turns swampy and fetid. The area is difficult terrain. The sludge at the bottom of the morass animates into diminutive sludge beasts that have a demonic appearance. These don't function as normal creatures, but they swarm over creatures in the swamp and exude a noxious stench. The swamp deals 1d6 poison damage to creatures that end their turn in the area (basic Fortitude save). For each additional action you use when Casting the Spell, increase the burst's radius by 5 feet.\nHeightened (+2) The damage increases by 1d6, and the initial radius increases by 5 feet","source":{"provider":"PAIZO","sourceId":"iQD8OhhkwhvD8Blw","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.tattoo-whispers","name":"Tattoo Whispers","kind":"RITUAL","rank":3,"rarity":"RARE","traits":["auditory","linguistic","mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"tattoo inks and silver tattooing needles worth 20 gp for each secondary caster"},"targeting":{"range":{"kind":"TOUCH"},"target":"the secondary casters","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting (expert)","secondaryChecks":"Arcana, Occultism","secondaryCasters":0},"description":"You carefully tattoo the same design upon each secondary caster. The tattoo can be of any shape or symbol, but it must include a mouth. The tattoo fades naturally over the course of 1 month.\n\nCritical Success The tattoos on the secondary casters are all magically linked for 1 week, providing a semi-telepathic bond. Each secondary caster can communicate secretly with any other secondary casters at any time by mouthing words but making no sound. The person receiving a message must be within 120 feet of the sender, must be within the sender's line of sight, and must have their tattoo uncovered. The mouth of the tattoo moves to match the words, which the tattoo whispers, but only the tattoo's bearer can hear it.\n\nSuccess As critical success, but the effect lasts for 1 day.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual has no effect and creates a backlash of persistent mental static. All casters are Stupefied 1 for 1 day.","source":{"provider":"PAIZO","sourceId":"32NpJbPblay77K6v","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tempest-cloak","name":"Tempest Cloak","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shroud one creature in a cloak of fierce, howling winds, shielding it from attacks and making it difficult to approach. The twisting shield of wind creates difficult terrain in a surrounding the target. The target also gains a +2 circumstance bonus to its AC against physical ranged attacks, such as attacks made with bows, javelins, or slings. In addition, the sound of the swirling storms makes it easier for the target to ignore anything it doesn't want to hear, granting the target a +2 circumstance bonus to all defenses against auditory effects.","source":{"provider":"PAIZO","sourceId":"70BjbNRVc4OTLAgN","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.temporal-twin","name":"Temporal Twin","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"one willing ally","area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pull a fleeting duplicate of your ally from the recent past. The duplicate appears in an unoccupied space of your choice within 30 feet of you and repeats a basic single action the target took since the end of your last turn, such as making a Strike or Interacting to pull a lever. Because the other basic single actions don't produce much of a result on their own, this is typically used for Strike and Interact, though occasionally it could be useful to have a temporal twin Stride through a potentially dangerous area to expose a hazard. Immediately after you cast this spell, the target ally spends a reaction to create the duplicate, makes any decisions, and rolls for the repeated action, such as choosing a target for a Strike and making the attack roll. If the ally doesn't have a reaction to spend, temporal twin fails. Use the duplicate's location for determining flanking, cover, and the like. Using this spell requires remembering what your ally did, and if you don't remember the details, the GM might not allow you to cast temporal twin.\n\nThis action can't be used for anything but a basic single action, nor can it use limited resources. The action can have a different target than the original action but must be very similar in form. For example, if the original action were to Interact to pull a lever, the time duplicate could pull a different lever but couldn't turn a doorknob or pick up an item from a table. Being pulled through time to create a twin destabilizes the target's timeline. Once an ally has been the target of temporal twin, they're temporarily immune for 1 day.","source":{"provider":"PAIZO","sourceId":"1bXLp8cyIKFjZtVx","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.the-four-hunters","name":"The Four Hunters","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["auditory","concentrate","linguistic","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 or more creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"This is a story of four evenly matched hunters who sought to capture a falling star. Each hunter was known by the region they came from, and this spell focuses on one of their attributes. When you cast this spell, you must choose East, North, South, or West.\n- East was steady and optimistic. The target gains 5 temporary Hit Points and a +1 status bonus to Athletics for 1 round.\n- North was careful and cautious. The target can Step as a free action and gains a +1 status bonus to Survival for 1 round.\n- South was clever and cunning. The target becomes and gains a +1 status bonus to Stealth for 1 round.\n- West was bold and competitive. The target gains a +10-foot status bonus to their land Speed and a +1 status bonus to Acrobatics for 1 round.\n1 You quickly remind yourself of the story, granting only yourself the benefit.\n\n2 You tell a trusted ally within 30 feet this story, granting them the benefit.\n\n3 You impart this tale on all of your allies within 30 feet, granting them the benefit.","source":{"provider":"PAIZO","sourceId":"EdRYr7HmLm9wr71X","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.thief-of-fortune","name":"Thief of Fortune","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"one beneficial spell effect currently affecting a creature, with a duration of 10 minutes or less","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Seeing another creature improve themself with magic, you reach out and seize its benefits for yourself. Attempt a counteract check against the target spell effect. If you successfully counteract the effect, the effect does not end. Instead, you gain the effect of the target spell as well. If you would not be a valid target for the spell, you do not gain any of its benefits.\n\nThe spell's duration is halved as you siphon off its magical energy for yourself. Each round that both you and the original creature are affected by the spell counts for two rounds when determining the spell's duration. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"uGi6t3cypb93mgyV","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.threatening-mimicry","name":"Threatening Mimicry","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","emotion","fear","focus","illusion","manipulate","mental","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You appear larger and stronger to nearby creatures, appearing to possess threatening features like antlers, claws, or poison to their senses. Each non-allied creature in the area must attempt a Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Frightened 1. This condition doesn't decrease at the end of its turn if it damaged you during that turn.\n\nFailure As success, but Frightened 2.\n\nCritical Failure As success, but Frightened 3.","source":{"provider":"PAIZO","sourceId":"s0i3S4fg2XDQX4a7","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.threefold-aspect","name":"Threefold Aspect","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"This spell allows you to change between three versions of yourself of different ages: a maiden (young adult), a mother (adult), or a matriarch (elderly). Choose one when you Cast the Spell. While the spell lasts, you can change the age to any of the three or to your natural age by Sustaining the spell. Your form always looks like you regardless of the age, and creatures who know you still recognize you and can tell your age is different.\n\nThreefold aspect alters your physical appearance and personality to present an authentic version of yourself at various ages. This grants you a +4 status bonus to Deception checks to pass as the chosen age, and you can add your level as a proficiency bonus to these checks even if you're untrained. Furthermore, unless a creature specifically uses a action or otherwise carefully examines you, it doesn't get a chance to notice that you aren't at your true age. You can Dismiss this spell.","source":{"provider":"PAIZO","sourceId":"MNiT0dHol5fEcKlz","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.thunderburst","name":"Thunderburst","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["air","concentrate","focus","manipulate","oracle","sonic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"2d6","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d6","1":"2d6"},"areaFeet":5},"counteraction":false,"ritual":null,"description":"You create a powerful blast of air and a loud peal of thunder, dealing 2d6 bludgeoning damage and 2d6 sonic damage. Each creature in the area must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is for 1 minute.\n\nCritical Failure The creature takes double damage and is deafened for 1 hour.\nHeightened (+2) Each type of damage increases by 2d6, and the area increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"LFSwMtQVP05EzlZe","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.time-jump","name":"Time Jump","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You leap forward a few seconds in time, appearing across the battlefield in the blink of an eye. You gain 2 actions, each of which must be used to Leap, Stand, Step, or Stride. If you have an appropriate Speed, you can add , , , or to this list. While you take these actions, time pauses. All other creatures are completely unaware of your actions, can't speak, and can't use any actions that would be triggered by your movement.\n\nWhile you're taking these actions, you can't take any other actions, including any that would be triggered by the move actions. Once the actions are complete, time starts again, and to onlookers, you seem to have suddenly teleported across the distance you traveled. Leaping forward through time is disorienting, so if you use time jump again within 1 minute of using the spell, you become Stupefied 4 for 1 minute.","source":{"provider":"PAIZO","sourceId":"qJGW6BbIcU6sfA1d","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.time-pocket","name":"Time Pocket","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"one item of 1 Bulk or less that a willing creature is holding","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fling the target item forward in time and link it to the future of the creature holding it. The item disappears. When the spell ends, the item reappears with the creature that was holding it when you Cast the Spell. If the creature has enough hands free to hold the item, it appears in their hands. Otherwise, it falls to the ground in the creature's space.\n\nYou can Dismiss the spell, and it automatically ends if you're reduced to 0 Hit Points or cast time pocket again.","source":{"provider":"PAIZO","sourceId":"0Rl3W7kiq9xVZRcr","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.time-skip","name":"Time Skip","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature other than yourself","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You manipulate time around your ally, pushing them forward a few moments in time. The target is on its next turn and can use the action only to Step, Stride, or Strike.\nHeightened (6th) You can affect up to four willing creatures other than yourself within range.","source":{"provider":"PAIZO","sourceId":"LbqunTurwXB3u9Vp","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.trade-items","name":"Trade Items","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 item you're holding and 1 item in another creature's possession you can see, each no more than light Bulk","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You magically swap an item you're holding for another that someone else has. The second item appears in the hand you were holding the first item (or it falls to the ground in your square if you're unable to hold it), and the first item appears in the same place on the other creature's possession where the second item was (held in a hand or attached to a belt, for instance). If the second item is in the possession of a creature unwilling to relinquish it, they can prevent the transposition with a successful Reflex save.\nHeightened (5th) Each object's maximum Bulk increases to 1. If one of the items is 1 Bulk and the other isn't, an unwilling creature gains a +2 circumstance bonus to their saving throw.","source":{"provider":"PAIZO","sourceId":"rSpGzCyYrTMiWQoG","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.transcribe-conflict","name":"Transcribe Conflict","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause a sheet of paper to appear in your hand, and a moment later a detailed description of a combat you experienced within the last hour is recorded on that sheet of paper in a language that you know of your choice. The description is detailed enough that anyone who spends 1 minute reading the page can attempt to Recall Knowledge about the event as if they had been there, but the primary purpose of the transcribed conflict is to give you additional insight into the fight by allowing you to study the conflict and learn from errors or tactical blunders participants in the battle may have committed.\n\nWhen you cast this spell, choose a type of foe in the fight you transcribed and attempt to Recall Knowledge about that foe using your spell DC-10 instead of your skill modifier in an appropriate skill to do so. For this action, you can't use any special abilities, reactions, or free actions that trigger when you Recall Knowledge. If you are successful, you not only learn information about that foe as determined by the GM, but for the remainder of transcribe conflict's duration, you gain a +1 status bonus to Initiative checks in combats where you face that exact kind of foe. For example, if you made the check against a wrath demon, the bonus would apply only to wrath demons, not to other demons. The GM decides if a foe who is disguised grants you this bonus.\n\nHeightened (5th) The bonus to initiative increases to +2 and the duration increases to 8 hours.\n\nHeightened (8th) The bonus to initiative increases to +3 and the duration increases until the next time you do your daily preparations, and the status bonus to Initiative checks applies to any allies who took part in the fight you transcribed as long as they are within 30 feet of you when you cast the spell.","source":{"provider":"PAIZO","sourceId":"YZnLggKDHkMY4cnw","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.travel-by-turtle","name":"Travel by Turtle","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate","mythic"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure an intelligent sea turtle, who agrees to carry you upon its shell on a water journey. This turtle must be conjured into a large body of water within range, such as a lake or broad river. The turtle conjured is Large, is capable of carrying one Medium creature or up to four Small creatures, and has a swim Speed of 30 feet. The turtle doesn't engage in combat and doesn't put itself intentionally into harm's way, but it does convey you to a destination of your choice and follows your suggestions. The turtle otherwise functions as a boat, save that it controls itself and doesn't need to be piloted.\nHeightened (5th) The turtle's size increases to Huge, making it capable of carrying one Large creature, up to four Medium creatures, or up to 16 Small creatures. Its swim Speed increases to 40 feet, and the duration increases to 1 day.\n\nHeightened (7th) The turtle's size increases to Gargantuan, making it capable of carrying one Huge creature, up to four Large creatures, up to 16 Medium creatures, or up to 32 Small creatures. Its swim Speed increases to 50 feet, and the duration increases to 1 week.\n\nHeightened (9th) The turtle's size increases to Gargantuan, making it capable of carrying two Huge creatures, up to eight Large creatures, up to 32 Medium creatures, or up to 64 Small creatures. Its swim Speed increases to 60 feet, and the duration increases to 1 month.","source":{"provider":"PAIZO","sourceId":"dk3XIx0ExDRMcN5z","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unblinking-flame-revelation","name":"Unblinking Flame Revelation","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1},"requirements":"Your previous action was a successful unarmed Strike."},"targeting":{"range":{"kind":"NONE"},"target":"the creature you hit","area":null},"duration":{"text":"2 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You light your foe with revealing flame. The GM attempts a secret counteract check against each illusion affecting the creature; on a success, you suppress the illusion for the duration, rather than end the effect.","source":{"provider":"PAIZO","sourceId":"VBNevVovTCpn04vL","book":"Pathfinder Lost Omens World Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unbreaking-wave-advance","name":"Unbreaking Wave Advance","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","water"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"3d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You unleash a mighty wave from your hand that buffets back your foes. Each creature in the area must attempt a Fortitude saving throw. If a creature pushed by unbreaking wave advance would be pushed into a solid barrier or another creature, it stops at that point and takes 3d6 damage.\n\nSuccess The creature is unaffected.\n\nFailure The creature is pushed 10 feet.\n\nCritical Failure The creature is pushed 20 feet.\n\nHeightened (+1) The damage for pushing a creature into a solid barrier increases by 1d6.","source":{"provider":"PAIZO","sourceId":"ytboJsyZEbE1MLeV","book":"Pathfinder Lost Omens World Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.undertow","name":"Undertow","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","incapacitation","water"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an area of water 20 feet deep. The DC for Athletics checks to Swim in the area is equal to your spell DC. A creature that starts its turn in the area must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes 2d6[bludgeoning] damage.\n\nFailure The creature takes 4d6[bludgeoning] damage and takes a –2 circumstance penalty to Athletics checks to Swim and a –10-foot circumstance penalty to its swim Speed, if it has one, until it leaves the area.\n\nCritical Failure As failure, and the creature is pulled 10 feet down.","source":{"provider":"PAIZO","sourceId":"4VsCGrIz07NrMaZA","book":"Pathfinder Lost Omens High Seas","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfolding-wind-rush","name":"Unfolding Wind Rush","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You travel on a rushing wind. Move two times: two Strides, two Steps, or one Stride and one Step (in either order). You can Stride or Step into the air during this movement, moving upward at a 45-degree angle at most; if you end your movement in the air, you fall after taking one action or when your turn ends, whichever comes first. A appears in all the spaces you left during this movement, lasting for 1 round.\n\nHeightened (5th) The wall of wind lasts 3 rounds.","source":{"provider":"PAIZO","sourceId":"tvO6Kmc2pQve9DC5","book":"Pathfinder Lost Omens World Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unravel-knowledge","name":"Unravel Knowledge","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","hex","manipulate","mental","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron reaches into the target's mind, plucking out their past training like pulling a thread from a cloth. Choose a single action, activity, or spell you know the target can use, such as from seeing it previously or identifying the creature's capabilities with a Recall Knowledge check. You could select, for example, the Strike action, the action, a dragon's breath, or the spell if you were aware the target could use them. The target attempts a Will save.\nSuccess The target is unaffected.\n\nFailure The target's memories of their ability grow foggy. The first time they use the chosen ability each round, they take 3d8 mental damage. This ability is less effective if you choose an ability almost anyone can use; the target takes 3d4 mental damage instead if you choose a basic action (such as Strike, Stride, or Raise a Shield) or a skill action that can be used untrained (such as or Hide).\n\nCritical Failure As failure, and the target takes a –2 status penalty to any check or DC for the ability the first time they use it each round.\n\nHeightened (+1) The damage increases by 1d8, or by 1d4 for a basic action or untrained skill action.","source":{"provider":"PAIZO","sourceId":"EFLXGyIz2HZVSmll","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unseasonable-squall","name":"Unseasonable Squall","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You issue a blast of sudden wind that ripples outward from the center of the burst. The wind extinguishes small non-magical fires, disperses fog and mist, scatters objects of light Bulk or less, and pushes unsecured objects of 1 Bulk or less 5 feet away from the spell's origin point. Each Medium or smaller creature in the area when you Cast the Spell or that moves into spell's area must attempt a Fortitude saving throw.\n\nSuccess The creature is unaffected.\n\nFailure The creature is knocked . If the creature was Flying, it gets a critical failure instead.\n\nCritical Failure The creature is pushed 30 feet away from the center of the burst, is knocked Prone, and takes 2d6 bludgeoning damage.","source":{"provider":"PAIZO","sourceId":"TT9owkeMBXJxcERB","book":"Pathfinder #151: The Show Must Go On","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unseen-heralds","name":"Unseen Heralds","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":["attack","auditory","illusion","visual"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare oils, salts, and herbs worth a total value of 15 gp"},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"SQUARE","feet":100}},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert)","secondaryChecks":"Arcana or Occultism (whichever isn't used for the primary check), Diplomacy","secondaryCasters":2},"description":"Although this spell has spread throughout the Inner Sea, it likely came first from Nex, where it is used to raise alarms or notify the populace of new policies. In any case, the ritual works by placing several simple illusions throughout the area, allowing the caster to transmit their voice throughout the area.\n\nCritical Success The ritual creates six 'mouths', like , at places you select within the area. By spending a single action with the concentrate trait, you can command the mouths to speak—they can say anything you like, and you can set them to repeat messages or announcements at any interval you choose. You can also choose to have only certain mouths speak. Any secondary casters you include in the ritual, even beyond the two required, can speak through the mouths in the same way you can.\n\nSuccess As critical success, but the ritual creates three mouths.\n\nFailure The ritual has no effect.\n\nCritical Failure The mouths form, and promptly start screaming, gibbering, and/or swearing at passers-by—it is impossible to get any rest or relaxation within hearing range of the mouths until their magic wears out in about a day.\n\nHeightened (6th) The area of the ritual is now 1 mile × 1 mile and it produces 30 mouths (60 on a critical success). The cost of the ritual increases to 300 gp.\n\nHeightened (9th) The area of the ritual is now 100 miles × 100 miles and it produces 500 mouths (1000 on a critical success). You can place mouths based on criteria. The cost of the ritual increases to 5,000 gp.","source":{"provider":"PAIZO","sourceId":"bK7EZFCxZgDcko6D","book":"Pathfinder Wake the Dead #2","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.untwisting-iron-buffer","name":"Untwisting Iron Buffer","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send currents of protective ki to the surface of your body that protect you from harm, at least until your enemies dissipate them. You gain 15 temporary Hit Points, which last for up to 3 rounds.\nHeightened (+1) The temporary Hit Points increase by 5.","source":{"provider":"PAIZO","sourceId":"FPnkOYyWIaOzkmqn","book":"Pathfinder Lost Omens World Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vampiric-feast","name":"Vampiric Feast","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","death","manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"6d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Your touch leeches the lifeblood out of a target to empower yourself. You deal 6d6 void damage to the target. You gain temporary Hit Points equal to half the void damage the target takes (after applying resistances and the like). You lose any remaining temporary Hit Points after 1 minute.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"N1Z1oLPdBxaSgrEE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.vector-screen","name":"Vector Screen","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"LINE","feet":10}},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You set up a transparent, rippling screen of telekinetic energy that seizes small, fast-moving projectiles. Creatures can pass through the screen, but ammunition from physical ranged attacks—such as arrows, bolts, sling bullets, and other objects of similar size—is automatically trapped in the screen, clattering to the ground once the spell ends. Attacks with bigger ranged weapons, such as javelins, take a –2 circumstance penalty to their attack rolls if their paths pass through the screen. Massive ranged weapons and spell effects that don't create physical objects pass through the screen with no penalty.\nHeightened (5th) The screen is 20 feet long.\n\nHeightened (6th) The screen is 20 feet long and can interfere even with massless attacks, like magical blasts or gouts of flame. The screen imposes a –2 circumstance penalty to the attack rolls of spell effects even if they don't create physical objects. It also protects against area effects that pass through the screen, granting standard cover to creatures on the opposite side of the screen from the center or origin point of an area.","source":{"provider":"PAIZO","sourceId":"a0AMgATvQGwDR5dR","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.veil-of-privacy","name":"Veil of Privacy","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature or object","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You erect protective wards that make the target difficult to detect via magic. Veil of privacy attempts to counteract all detection, revelation, and scrying effects used against the target or the target's gear throughout the duration, counting cantrips as 1st-rank spells for this purpose. Successfully counteracting a spell that targets an area or multiple targets negates the effects for only veil of privacy's target.","source":{"provider":"PAIZO","sourceId":"EoKBlgf6Smt8opaU","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wall-of-radiance","name":"Wall of Radiance","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fire","light","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"h5zzrh1xmy9k57m6","formula":"2d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create a thin wall of brilliant light in a straight line up to 60 feet long and 10 feet high. You must create the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. The wall stands vertically and, if you wish, can be of a shorter length or height. Creatures adjacent to the wall are . Creatures that move through the wall take 2d6 fire damage (basic Fortitude save) as the concentrated light burns them.\nHeightened (4th) The light makes it difficult to discern creatures on the other side. Creatures are to other creatures on the opposite side of the wall from them. The fire damage increases to 3d6.","source":{"provider":"PAIZO","sourceId":"HWrNMQENi9WSGbnF","book":"Pathfinder #172: Secrets of the Temple-City","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.wall-of-shadow","name":"Wall of Shadow","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","darkness","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You form a wall of pure darkness in a straight line up to 60 feet long and 10 feet high. You must create the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. The wall stands vertically and, if you wish, can be of a shorter length or height. The wall prevents light from passing through and appears as a sheet of pure darkness to creatures observing it.\n\nCreatures without darkvision or those unable to see through darkness can't see creatures on the other side of the wall. The wall is too thin for creatures to in the darkness itself, but creatures can Hide from creatures on the other side of the wall as normal.\nHeightened (5th) Creatures with darkvision (but not greater darkvision) can barely see through the wall. They treat targets seen through the wall as .\n\nHeightened (7th) Creatures with greater darkvision can barely see through the darkness. They treat targets seen through the wall as concealed. All other creatures are unable to see through the darkness at all.","source":{"provider":"PAIZO","sourceId":"DeF63UTmr7rchF60","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wall-of-thorns","name":"Wall of Thorns","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"You grow a wall of thorny brambles from the ground. You create a 5-foot-thick wall of brambles and thorns in a straight line up to 60 feet long and 10 feet high. You must create the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. The wall stands vertically. If you wish, the wall can be of a shorter length or height. Everything on each side of the wall has cover from creatures on the opposite side, and the wall's spaces are difficult terrain. For every move action a creature uses to enter at least one of the wall's spaces, that creature takes 3d4 piercing damage.\n\nEach 10-foot-by-10-foot section of the wall has AC 10, Hardness 10, and 20 Hit Points. It's immune to critical hits and precision damage. A destroyed section can be moved through freely.\nHeightened (+1) The Hit Points of each section of the wall increase by 5, and the piercing damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"KsWhliKfUs3IpW3c","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.wall-of-virtue","name":"Wall of Virtue","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","holy","light","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"31ztnkdh2g12fivc","formula":"1d8","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false},{"id":"9oaina411wu1igyn","formula":"1d8","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"31ztnkdh2g12fivc":"1d8","9oaina411wu1igyn":"1d8"}},"counteraction":true,"ritual":null,"description":"You create a translucent wall of light, which draws power from the celestial realms. You create either a 5-foot-thick wall in a straight line up to 60 feet long and 10 feet high or a 5-foot-thick, 10-foot-radius ring with the same height. The wall sheds bright light for 20 feet on each side and dim light for the next 20 feet.\n\nIf the light passes through an area of magical darkness or targets a creature affected by magical darkness, wall of virtue attempts to counteract the darkness.\n\nAny creature that crosses the wall or is occupying the wall's area at the start of its turn takes 1d8 spirit damage and 1d8 vitality damage.\n\nHeightened (+2) The spirit damage increases by 1d8, and the vitality damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"ZJOQBqkNErZu1QAa","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.wall-of-water","name":"Wall of Water","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Raising your hand in the air, you call a massive wave onto the battlefield. The wall stays upright in a straight line that is 60 feet long, 10 feet high, and 5 feet thick.\n\nAny non-magical fires within the wall of water's area that are its size or smaller are put out instantly. It also attempts to counteract any magical fires in its area. Both of these effects happen when the spell is cast and whenever a fire enters the wall's area. If the wall fails to counteract a given fire, it can't counteract that fire for the duration of the spell.\n\nBludgeoning or slashing projectiles can't pass through the wall, and piercing projectiles have their range increments halved if they pass through the wall. A creature traversing the wall of water needs to Swim through. The rules of aquatic combat apply to creatures traversing the wall of water, targeting creatures within the wall, or passing through the wall. For instance, a bludgeoning or slashing melee attack targeting a creature in the wall would take a -2 circumstance penalty.","source":{"provider":"PAIZO","sourceId":"LNOwaJAkCfsgTKgV","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wall-of-wind","name":"Wall of Wind","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a barrier of gusting winds that hinders anything moving through it. The wall of swirling winds is 5 feet thick, 60 feet long, and 30 feet high. The wall stands vertically, but you can shape its path. Though the wall of wind distorts the air, it does not hamper sight. The wall has the following effects.\n\n- Ammunition from physical ranged attacks-such as arrows, bolts, sling bullets, and other objects of similar size-can't pass through the wall. Attacks with bigger ranged weapons, such as javelins, take a -2 circumstance penalty to their attack rolls if their paths pass through the wall. Massive ranged weapons and spell effects that don't create physical objects pass through the wall with no penalty.\n\n- The wall is difficult terrain to creatures attempting to move overland through it. Gases, including creatures in , can't pass through the wall.\n\n- A creature that attempts to fly through the wall using a move action must attempt a Fortitude save.\n\nCritical Success The creature can move through the wall normally this turn.\n\nSuccess The flying creature can move through the wall this turn, but the wall is difficult terrain.\n\nFailure The wall stops the movement of the flying creature, and any remaining movement from its current action is wasted.\n\nCritical Failure As failure, and the creature is pushed 10 feet away from the wall.","source":{"provider":"PAIZO","sourceId":"it4ZsAi6XgvGcodc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wanderers-guide","name":"Wanderer's Guide","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon the beyond to guide your route. When you Cast this Spell, choose a destination; you receive an inspired route to that destination, allowing you and allies who travel overland with you to reduce the movement penalty from difficult terrain by half for the duration, as long as you don't deviate from the inspired route. This doesn't have any effect on movement during encounters. If you use this ability again before the duration is over, this effect ends and is replaced by that of the new route.","source":{"provider":"PAIZO","sourceId":"ppA1StEigPLKEQqR","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.warding-aggression","name":"Warding Aggression","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"up to 1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel a magical ward through your attack and attempt to plant it on a foe. This ward increases your defenses against that foe, as long as you keep attacking that foe to maintain it. Make a melee Strike with a weapon or unarmed attack against a foe. In addition to the normal effects of the Strike, it has the effects below. Warding aggression ends if the foe you attacked dies or at the end of any turn in which you didn't hit that foe with a melee Strike.\nCritical Success You gain a +3 status bonus to AC against the foe for 1 round and a +2 status bonus to AC against the foe for the remaining duration.\n\nSuccess You gain a +2 status bonus to AC against the foe.\n\nFailure You gain a +1 status bonus to AC against the foe.\n\nCritical Failure You gain no additional effect.","source":{"provider":"PAIZO","sourceId":"CIjj9CU5ekeq1oLT","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.warning-stripes","name":"Warning Stripes","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","morph","poison","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"pO0jWffyBOsayMks","formula":"2d8","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"pO0jWffyBOsayMks":"1d8"}},"counteraction":false,"ritual":null,"description":"Your skin becomes painted with vivid stripes or bright aposematic swirls, warning other creatures of its toxic qualities. Any creature that touches you or hits you with an unarmed melee attack takes 2d8 poison damage. If you have an animal companion, you can cast this spell on them instead, with a range of 30 feet.\n\nHeightened (+2) The poison damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"D4kArD91fFiREvC6","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.web-of-eyes","name":"Web of Eyes","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 5 willing creatures","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You place an scrying sensor on each target just above their eyes. Each sensor looks where that target looks, and all the targets can link their vision briefly to help notice things one target sees but the others might not. Each target can use an action, which has the concentrate trait, to share what it sees with any number of other targets until the start of its next turn. Only one creature can share its vision at a time, so if another target takes this action, the effect ends for any target that was previously sharing its vision.\n\nThis improves how well the recipients can perceive anything the sharing creature is looking at. For instance, if a creature is undetected to a recipient but observed by the sharing creature, the creature becomes observed by the recipient as well. Typically, the creature is seen as a glowing outline superimposed on its position. This might allow the recipient to target a creature it couldn't otherwise; however, cover and line of effect still might prevent or impede targeting and attacks. This can only improve the recipient's vision, not reduce it; for example, if an enemy was undetected by the sharing creature and observed by a recipient, the recipient would still clearly observe the enemy.\n\nOnce the vision sharing stops, the benefit ends. Whether a creature is hidden or undetected is still based on the last information a target had before the vision sharing ended. For example, that means if a creature is behind a wall but hasn't moved, it's still hidden rather than undetected by a recipient that witnessed its current position.","source":{"provider":"PAIZO","sourceId":"XQSPJHOf3TyfqvgS","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.whirling-flames","name":"Whirling Flames","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5,"text":"up to two 5-foot bursts that don't overlap"}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"5d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"3d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You call forth a storm of whirling flames, engulfing all creatures in that area and dealing 5d6 fire damage with a basic Reflex save.\n\nHeightened (+2) The damage increases by 3d6, and you can add another non-overlapping 5-foot burst to the area.","source":{"provider":"PAIZO","sourceId":"Wi2HcreCfujKiCvW","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.whirling-scarves","name":"Whirling Scarves","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself in a vortex of whirling colorful scarves of force that obfuscate you and disorient your foes. You gain the benefits of the condition, but only against ranged and melee attacks. When a melee attack fails to hit you because of the flat check for the concealed condition, the scarves snag the weapon or unarmed attack, and the creature takes a –1 circumstance penalty to further attacks with that weapon or unarmed attack until the end of its turn (or the end of its next turn, if it wasn't the creature's turn). The timing of the scarves' movement is harder to predict for ranged attackers, so the flat check for the concealed condition against ranged attacks increases from DC 5 to DC 6. You can Dismiss this spell.\nHeightened (+2) The circumstance penalty to further attacks with a melee weapon or unarmed attack the scarves snag increases by 1. The DC of the flat check for the concealed condition against ranged attacks increases by 1.","source":{"provider":"PAIZO","sourceId":"k9x6bXXpIgAXMDsx","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wild-allegiance","name":"Wild Allegiance","kind":"RITUAL","rank":3,"rarity":"RARE","traits":["trial"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"animal food worth a total value of 150 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Diplomacy (expert)","secondaryChecks":"Nature, Religion","secondaryCasters":1},"description":"To many, the animals of Tian Xia are simply beasts to be conquered or harvested, but this isn't how all of the gods intended it. You approach, feed, and commune with the most notably hostile beasts in an effort to forge a true friendship and allegiance with the natural world.\n\nWantonly attacking or killing animals is anathema to this ritual and immediately ends its benefits. If the ritual is ended in this way, you must conduct an ritual before attempting this ritual again.\nCritical Success As success, except you can instead resolve a conflict with one animal of level 15 or higher.\n\nSuccess You declare your allegiance to the wild and are bound by the ritual's anathema, but you still must prove yourself. Once you've nonviolently resolved conflicts with three different animals of a higher level than yours, you gain the feat.\n\nFailure Your actions don't impress the gods of the wilds.\n\nCritical Failure You deeply offend the gods you were trying to impress, and they send a sign of displeasure, often an animal attack. You must conduct an atone ritual before attempting this ritual again.","source":{"provider":"PAIZO","sourceId":"BBw5oGFvoQc3gg52","book":"Pathfinder Lost Omens Tian Xia World Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wings-of-the-valkyrie","name":"Wings of the Valkyrie","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Powerful feathered wings—usually vibrant white or jet black—emerge from your back, granting you a fly Speed equal to your Speed. You can use these wings to attempt to a creature; you don't need a free hand to do so, and you can roll using your spell attack modifier instead of your Athletics skill for the check. When this spell's duration ends, if you're still flying, you float to the ground, as .\n\nHeightened (5th) The duration increases to 1 minute.","source":{"provider":"PAIZO","sourceId":"9ZwpT9RDwCxhYQXd","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.winters-breath","name":"Winter's Breath","kind":"RITUAL","rank":3,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"15 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":40},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Cooking Lore or Tea Lore (expert)","secondaryChecks":"Diplomacy or Society","secondaryCasters":1},"description":"The cold and dour months of winter are an excellent time to gather with friends and family to enjoy a pot of hot tea. The so-called \"breath\" in this ritual refers to the steam that wafts up from a freshly brewed cup while held in the hands and inhaled. Despite the ritual's name, it can be cast during any season, but unless it's cast during winter, the DCs for successfully casting winter's breath increase by 2 (or by 4 if the ritual is cast during summer).\n\nWhen you cast this ritual, you call forth a magical pavilion consisting of a colorful tent or decorate an area within range with a large number of colorful banners. In either case, the ritual also creates a full supply of teas and tea ware for the casters to use and serve up to six guests (which can include the casters). During the ritual, all the guests must be polite and well-mannered. The tea created by winter's breath is always delicious, but the effects of the tea and taking part in the ceremony of its serving depend on the success of the magic. At the ceremony's end, the ritual is completed, and you and the secondary caster attempt your checks as normal. If the ceremony is interrupted at any point, the tea vanishes and the ritual is disrupted.\nCritical Success The ceremony is a true delight. The tea casts , , , and at a rank equal to that which winter's breath was cast on each guest. Each guest also gains 10 temporary Hit Points and a +1 status bonus to saves against emotion effects for the next 12 hours.\n\nSuccess As critical success, except guests must choose which one of the five spells are cast on them, and they don't gain the status bonus to saves.\n\nFailure The tea leaves a bitter, unpleasant taste in the mouth, and no benefits are granted.\n\nCritical Failure Rather than invigorate and delight, the tea is disappointing and depressing. You and your guests are Sickened 3 and can't reduce the condition for 12 hours.\nHeightened (+1) The spells associated with a success or critical success are heightened by 1 rank, and the temporary Hit Points granted are increased by 2.","source":{"provider":"PAIZO","sourceId":"oYxxcgszpT242sEi","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wooden-double","name":"Wooden Double","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["manipulate","wood"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You're critically hit by a damage-dealing effect or a Strike.\n\nA wooden double appears out of nowhere and takes the blow in your place. Take a Step action. A wooden block of your size and roughly shaped like you appears in the space you left and absorbs the hit. This block has Hardness 5 and 20 Hit Points. If the wooden block is destroyed, you take any excess damage that the block didn't absorb. After taking the blow, the wooden block collapses into a pile of splinters and dust.\n\nHeightened (+1) The block's Hit Points increase by 10.","source":{"provider":"PAIZO","sourceId":"aUMmmtPmBdCdVDed","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.achaekeks-clutch","name":"Achaekek's Clutch","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","curse","death","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You mark the holy symbol of Achaekek in a visible location on the target's body.\n\nCritical Success The target is unaffected.\n\nSuccess The target is marked by Achaekek's symbol. For 1 minute, the first time per round that the target gains Persistent Bleed Damage, they immediately take that amount of slashing damage as the mantis claws grow off the symbol and rake them.\n\nFailure As success, but the curse has an unlimited duration.\n\nCritical Failure As failure, but the DC on the target's flat check to remove persistent bleed damage increases to 20 (15 with particularly effective assistance).","source":{"provider":"PAIZO","sourceId":"IT1aaqDBAISlHDUV","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.adaptive-ablation","name":"Adaptive Ablation","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You take acid, cold, electricity, fire, or sonic damage.\nYou shift yourself to adapt to the mystical wavelengths of the energy damage, protecting yourself from further harm. You gain resistance 5 to the triggering energy type; you gain this resistance after you take the triggering damage, so it applies only to future damage you take during the duration.\n\nHeightened (+2) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"GoKkejPj5yWJPIPK","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.aerial-form","name":"Aerial Form","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You harness your mastery of primal forces to reshape your body into a Medium flying animal battle form. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal (such as an owl or eagle for bird), but this has no effect on the form's Size or statistics. While in this form, you gain the animal trait. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n- AC = 18 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 5 temporary Hit Points.\n\n- Low-light vision.\n\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +16, and your damage bonus is +5. These attacks are Dexterity based (for the purpose of the condition, for example). If your attack modifier for Dexterity-based unarmed attacks is higher, you can use it instead.\n\n- Acrobatics modifier of +16, unless your own modifier is higher.\n\nYou also gain specific abilities based on the form you choose:\n- Bat\n- Speed 20 feet, fly Speed 30 feet; precise echolocation 40 feet;\n\n- Melee a fangs, Damage 2d8 piercing;\n\n- Melee a wing (agile), Damage 2d6 bludgeoning.\n\n- Bird\n- Speed 10 feet, fly Speed 50 feet;\n\n- Melee a beak, Damage 2d8 piercing;\n\n- Melee a talon (agile), Damage 1d10 slashing.\n\n- Pterosaur\n- Speed 10 feet, fly Speed 40 feet; imprecise scent 30 feet;\n\n- Melee a beak, Damage 3d6 piercing.\n\n- Wasp\n- Speed 20 feet, fly Speed 40 feet;\n\n- Melee a stinger, Damage 1d8 piercing plus 1d6 persistent poison.\n\nHeightened (5th) Your battle form is Large and your fly Speed gains a +10-foot status bonus. You must have enough space to expand into or the spell is lost. You instead gain 10 temporary HP, attack modifier +18, damage bonus +8, and Acrobatics +20.\n\nHeightened (6th) Your battle form is Huge, your fly Speed gains a +15-foot status bonus, and your attacks have 10-foot reach. You must have enough space to expand into or the spell is lost. You instead gain AC = 21 + your level, 15 temporary HP, attack modifier +21, damage bonus +4 and double damage dice (including persistent damage), and Acrobatics +23.","source":{"provider":"PAIZO","sourceId":"NzXpEzcZAjuDTZjK","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.air-walk","name":"Air Walk","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target can walk on air as if it were solid ground. It can ascend and descend in this way at a maximum of a 45-degree angle.","source":{"provider":"PAIZO","sourceId":"b5sGjGlBf58f8jn0","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.airlift","name":"Airlift","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A massive rush of wind lifts, briefly carrying you and everything around you to a nearby destination. You, each creature in the area, and each item of 10 Bulk or lighter are lifted by this powerful gale. You and all affected creatures and objects Fly up to 60 feet and land on a solid surface, arriving in the same relative position to each other. If there wouldn't be enough room at the destination for everything you're bringing, the spell fails, though the GM might allow you to rearrange the group slightly to accommodate the spell.\n\nAny unwilling participant can attempt a Reflex save to avoid being carried along. The airlift doesn't carry items that are secured in place (such as a hinged door or a person manacled to a wall).\n\nHeightened (6th) The distance you Fly increases to 120 feet, and the Bulk limit of an item you can airlift increases to 20.","source":{"provider":"PAIZO","sourceId":"6XscENSWyYRHqK0A","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.amity-cycle","name":"Amity Cycle","kind":"RITUAL","rank":4,"rarity":"RARE","traits":["emotion"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"2 hours"}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"audience of up to 200 people","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Performance (expert)","secondaryChecks":"Crafting, Performance, Society","secondaryCasters":0},"description":"You perform an anbarit, which involves poetry reading, singing, music, and dancing. The primary caster can either act as a narrator throughout the performance or be one of the lead performers. The secondary casters can be dancers, musicians, or orators who participate in the anbarit.\n\nCritical Success For 1 week, all audience and cast members gain a +2 status bonus to Diplomacy checks to on other citizens of Thuvia and 10 temporary Hit Points, their minds filled with feelings of unity and camaraderie with the people from other cities in their nation. If they travel to a Thuvian city other than the one they are from and share part of the anbarit with others while under the ritual's effects, the listeners gain a +1 status bonus to Diplomacy checks to Make an Impression on other Thuvian citizens for 24 hours.\n\nSuccess The audience members are filled with feelings of unity and camaraderie for the people from other cities in their nation; they gain a +1 status bonus to Diplomacy checks to Make an Impression on other citizens of Thuvia for 24 hours.\n\nFailure The audience enjoys the performance but gains no benefit.\n\nCritical Failure The audience is disturbed by the performance and can receive no bonuses from emotion effects for one week.","source":{"provider":"PAIZO","sourceId":"me5E8UvbBrHe3dZh","book":"Pathfinder Adventure: The Enmity Cycle","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.anathematic-reprisal","name":"Anathematic Reprisal","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"Trigger A creature performs an act anathema to your deity.\n\nYou punish a creature that transgresses against your deity, drawing upon the anguish you feel upon seeing one of your deity's anathema committed. You can cast this spell only when a creature actively commits a unique act of anathema. For example, if creating undead were anathema to your deity, you could use anathematic reprisal on a necromancer who had just created undead in front of you, but not on an undead creature just for existing. You deal 4d6 mental damage to the target, but a basic Will save can reduce this damage. If it fails, it is also Stupefied 1 for 1 round. The creature is then temporarily immune for 1 minute.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"7tR29sQt35NfIWqN","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.anchoring-air","name":"Anchoring Air","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","concentrate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature attempts a melee Strike against you\nYou solidify the air around an incoming attack, catching it in a vise-like grip. The triggering creature must attempt a Reflex save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes a –2 circumstance penalty to the triggering Strike's attack roll.\n\nFailure The creature takes a –2 circumstance penalty to all attack rolls until the end of its turn.\n\nCritical Failure As failure, but the creature is also until the start of its next turn.","source":{"provider":"PAIZO","sourceId":"bCZP8N2C41gF10G2","book":"Pathfinder Lost Omens High Seas","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.aromatic-lure","name":"Aromatic Lure","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","emotion","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"Varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You override a target's olfactory senses, luring them to a specific location through tantalizing false scents. Select a single square within range that is not hazardous or occupied by a creature. The target is drawn to the selected location, becoming euphoric upon arrival. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is distracted by the tantalizing scents, becoming Stupefied 1 for 1 round.\n\nFailure The target is Stupefied 2 and moves toward the selected location via the most direct route possible for 1 round, bypassing any obvious hazards and enemies in the way.\n\nCritical Failure The target is Stupefied 4 and moves to the selected location via the most direct route possible for 1 round, bypassing any obvious hazards and enemies in the way. If the creature reaches the destination, it must remain in that location for [[/r 1d4 #rounds]]{1d4 rounds} but can otherwise act normally.\n\nHeightened (+2) You target 1 additional creature, selecting a different square within range as their destination.","source":{"provider":"PAIZO","sourceId":"LX4pCagYLpc9hEji","book":"Pathfinder Lost Omens Legends","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.artistic-flourish","name":"Artistic Flourish","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":15},"target":"1 item or work of art that fits entirely within the range","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform the target into a form that more closes matches your creative vision. It's clearly the same item, but with aesthetic details you choose. The target is a beautiful and impressive piece for its new quality, but the effect is obviously magical and temporary, so its monetary value doesn't change. If you're an expert in Crafting, the item grants a +1 item bonus to attack rolls if it's a weapon or skill checks if it's a skill tool. When you Cast this Spell, any previous casting ends.\n\nHeightened (7th) If you're a master in Crafting, the item grants a +2 item bonus.\n\nHeightened (10th) If you're legendary in Crafting, the item grants a +3 item bonus.","source":{"provider":"PAIZO","sourceId":"eb4FXf62NYArTqek","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ash-strewn-ending","name":"Ash-Strewn Ending","kind":"RITUAL","rank":4,"rarity":"RARE","traits":["death","mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"area":{"shape":"BURST","feet":1000}},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (mythic) or Performance (mythic)","secondaryChecks":"Crafting, Pharasma Lore, or Survival","secondaryCasters":3},"description":"Lo, speak of the hero-gods and their ash-strewn endings! Sing of their might as it falls on the land! Taste the bone and char that binds their life to yours! This ritual focuses on the burning of a mythic creature's corpse on a pyre in an outdoor location. Once the corpse has been reduced to ashes, the wind scatters those ashes across a 1,000-foot radius. As the ash lands on creatures within this radius, a fragment of the dead creature's mythic power flows into them.\nCritical Success Death has a lessened claim upon those in the ritual's area of effect. All creatures that were of a level equal to or lower than the level of the mythic creature incinerated as part of the ritual gain resistance 10 to void damage and a +2 status bonus to saving throws against death effects and to recovery checks.\n\nSuccess As critical success, but only as long as the creature remains in the ritual's area.\n\nFailure The ritual has no effect.\n\nCritical Failure Grief washes over the area, and the threat of death looms more closely over the casters, who all gain weakness 10 to void damage and a –2 status penalty to saving throws against death effects and to recovery checks. This is a curse effect.\n\nHeightened (6th) The area increases to a 1-mile radius, the duration increases to 1 month, the void resistance (or weakness) increases to 15, and the status bonus (or penalty) increases to +3.\n\nHeightened (8th) The area increases to 10 miles, the duration increases to 1 year, the void resistance (or weakness) increases to 20, and the status bonus (or penalty) increases to +4.\n\nHeightened (10th) As 8th rank, but one GM-selected non-mythic creature in the area becomes mythic. This creature's attitude and personality is favorable toward the primary caster.","source":{"provider":"PAIZO","sourceId":"QqMlN9VSHfD2v4Qv","book":"Pathfinder #218: Titanbane","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.asterism","name":"Asterism","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","light","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":150},"area":{"shape":"LINE","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area (continued) five 30-foot lines\nLines of burning starlight form a constellation around you. Draw five lines, one at a time; each line must anchor at you or a creature or object already connected to a previous line, and it must end at a creature or object within 30 feet of its anchor (possibly allowing the asterism to extend to its full 150-foot range). A creature that begins its turn in one of these lines or enters one of these lines on its turn takes 4d6 fire damage (basic Reflex save). A creature can take this damage only once per turn, even if it moves through several lines. Targets that are part of the asterism do not take damage from it. If the distance between two targets (or you and a target) ever exceeds 30 feet, the line of starlight between the two breaks, and any lines that now no longer have a direct path back to you also break. You can Dismiss the spell.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"KG7amdeXWc7MjGXe","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.atone","name":"Atone","kind":"RITUAL","rank":4,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense and offerings worth a total value of 20 gp × the target's level"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"another creature of up to 8th level who is a worshipper of the same deity or philosophy as you","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature or Religion (expert)","secondaryChecks":"Nature or Religion (whichever is used for the primary check)","secondaryCasters":0},"description":"You attempt to help a truly penitent creature atone for its misdeeds, typically actions anathema to your deity. If the creature isn't truly penitent, the outcome is always a critical failure. This ritual uses Nature if the target is a druid, and Religion in all other cases.\n\nCritical Success The creature receives absolution for its misdeeds, allowing it to regain standing with your deity. It regains any abilities it lost. Before the atonement is complete, the creature must perform a special quest or other task chosen by your deity, as befits its misdeeds. If completed during downtime, this task should take no less than 1 month. For 1 month, the target receives divine insight just before performing an act that would be anathema to your deity.\n\nSuccess As critical success, but the creature gains no special insight regarding its subsequent actions.\n\nFailure The creature does not receive absolution and must continue to meditate and redress its misdeeds. Any future atone rituals for the same misdeeds cost half as much and gain a +4 circumstance bonus to primary and secondary checks.\n\nCritical Failure The creature offends your deity and is permanently cast out from the faith. The creature can't rejoin your religion without a more direct intervention.\n\nHeightened (+1) Increase the maximum target level by 2 and the base cost by 20 gp.","source":{"provider":"PAIZO","sourceId":"7Fd4lxozd11MQ55N","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bestial-curse","name":"Bestial Curse","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","curse","manipulate","polymorph"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living humanoid","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tap into the target's inner being and curse it to become a bestial version of itself. The effect is based on its Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target's body gains minor bestial features. Its insides churn as they partially transform, causing it to be Clumsy 1 for 1 round. When it recovers from the clumsy condition, its features revert to normal, and the spell ends.\n\nFailure The target transforms into a bestial form for 1 hour. The target becomes clumsy 1 and gains weakness 1 to silver. It gains a claw, hoof, horn, or jaws Strike (your choice) that uses the target's unarmed Strike statistics except that the damage type changes to bludgeoning, piercing, or slashing, as appropriate. Whenever the target attempts to use any manipulate action, it must succeed at a flat or the action is lost.\n\nCritical Failure As failure, but the duration is unlimited.","source":{"provider":"PAIZO","sourceId":"VuPDHoVEPLbMfCJC","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blight","name":"Blight","kind":"RITUAL","rank":4,"rarity":"UNCOMMON","traits":["plant","void"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert)","secondaryChecks":"Survival","secondaryCasters":1},"description":"Area 1/2-mile-radius circle centered on you\n\nYou twist and stunt plants in the area, causing them to wither. In addition to other dangers from failing plant life, this decreases the crop yield for farms. If you cast this ritual in an area affected by plant growth, blight attempts to counteract plant growth instead of producing its usual effect.\n\nCritical Success Completely spoil the crop yield in the area, or decrease the yield by half in an area with up to a 1-mile radius.\n\nSuccess Decease the crop yield in the area by half.\n\nFailure The ritual has no effect.\n\nCritical Failure The flora in the area changes in an unexpected way, determined by the GM but generally as contradictory to your true desires as possible (for instance, enriching crops when you would prefer to blight them).","source":{"provider":"PAIZO","sourceId":"7yWXx3qC4eFNHhxD","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bloodspray-curse","name":"Bloodspray Curse","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","curse","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You inflict a curse upon the target that causes any wound to gush blood. The target must attempt a Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess For 1 minute, the first time each round that the target takes at least 10 (floor(@item.rank/2))d6[piercing]{piercing} or (floor(@item.rank/2))d6[slashing]{slashing} damage from a single Strike, it takes 2d6 additional damage of the same type.\n\nFailure As success, but when it takes the additional damage, it also takes (floor(@item.rank/2))d6[bleed].\nHeightened (+2) The additional damage increases by 1d6 and the persistent bleed damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"VXUrO8TwRqBpNzdU","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bottle-the-storm","name":"Bottle the Storm","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","electricity","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You would take electricity damage.\nWhen lightning is turned against you, you store the charge safely within yourself, unleashing it when the time is right. You gain electricity resistance 10 against the triggering effect. If you successfully prevent damage in this way, at any time during the spell's duration, you can spend a single action, which has the attack trait, to expend the charge and make a spell attack against the AC of a target within 60 feet. This attack deals electricity damage equal to the damage prevented by bottle the storm. If you Cast bottle the storm a second time before the original duration elapses, or if you do not make this attack within 1 minute, the stored charge dissipates harmlessly.\nHeightened (7th) The resistance increases to 15, and you can immediately make the spell attack granted by bottle the storm as part of the reaction used to Cast the Spell.\n\nHeightened (10th) The resistance increases to 20, and you can immediately make the spell attack granted by bottle the storm as part of the reaction used to Cast the Spell.","source":{"provider":"PAIZO","sourceId":"VUwpDY4Z91s9QCg0","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bridge-of-vines","name":"Bridge of Vines","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Vines sprout beneath your feet and extend away from you in a straight line up to 60 feet, forming a 10-foot-wide bridge that can cross over difficult terrain and low obstacles, as well as reach higher ground. The bridge has an AC equal to your spell DC, Hardness 10, and 20 Hit Points. It is immune to critical hits and precision damage. The bridge lasts either for the duration of the spell, until it is destroyed, or until you Dismiss the spell.\n\nWhile the spell is active, you and your allies can use the bridge normally. If any other creatures attempt to use the bridge, the vines attempt to trip and entangle them. They must attempt a Reflex save against your spell DC.\nCritical Success The target is unaffected.\n\nSuccess The target treats the length of the bridge as difficult terrain.\n\nFailure As success, and the target is knocked .\n\nCritical Failure As success, and the target is knocked prone and until it Escapes (with a DC equal to your spell DC) or the spell ends.\nHeightened (+1) The bridge's Hit Points increase by 10.","source":{"provider":"PAIZO","sourceId":"VUUWjeapcyLZabVA","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bursting-bloom","name":"Bursting Bloom","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","plant"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"CCRf3ezRsr91DEo0","formula":"6d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"Pw864Jw8qLF34TrG","formula":"1d6","damageType":"bleed","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"CCRf3ezRsr91DEo0":"3d6","Pw864Jw8qLF34TrG":"1d6"}},"counteraction":false,"ritual":null,"description":"You cause a rose bush to sprout from the chest of a foe, bursting out of its body and wrapping it in thorned vines. The target takes 6d6 piercing damage and 1d6 persistent bleed damage and must attempt a Fortitude save. When the target is no longer taking persistent bleed damage and is no longer encumbered, the rose bush withers away to nothing.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and no persistent damage.\n\nFailure The creature takes full damage and persistent damage and is for 4 rounds.\n\nCritical Failure The creature takes double damage and persistent damage and is encumbered for 1 minute.\n\nHeightened (+2) The initial damage increases by 3d6, and the persistent bleed damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"vGMbpV7GWIFPNUaZ","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.call-the-blood","name":"Call The Blood","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","death","manipulate","void"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"8d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"}},"counteraction":false,"ritual":null,"description":"With a word and gesture, you cause streams of blood to erupt from the target's mouth, nostrils, ears, or other facial openings and come rushing into your mouth. You deal 8d4 void damage to the target.\n\nIf the target takes damage, its blood flows into your mouth. If you're a living creature and don't have void healing, you're Sickened 2. If you're undead (or living but have void healing), you can choose to either gain temporary Hit Points equal to half of the void damage the target takes (after applying resistance and the like) and become for 1 round, or forgo the temporary Hit Points and become quickened for 1 minute. You can use this extra action only to Step, Stride, or Strike. You lose any remaining temporary Hit Points after 1 minute.\n\nHeightened (+1) The damage increases by 2d4.","source":{"provider":"PAIZO","sourceId":"S1Msrwi990FE7uMO","book":"Pathfinder #165: Eyes of Empty Death","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.call-the-ten","name":"Call the Ten","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 10 creatures, including yourself","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"Z4qB0jL7MHJobesW","formula":"4d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"Z4qB0jL7MHJobesW":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"The Ten Magic Warriors were the first of the Magaambya's students, and they come to your aid even now. An indistinct spirit appears near each target, each wearing a different mask of the Ten Magic Warriors. The spirits then either strike their designated targets with magical energy, dealing each one 4d6 spirit damage with a basic Fortitude save, or shield them, granting their target resistance 3 to physical and spirit damage until the beginning of your next turn. You designate which targets are attacked and which are shielded.\n\nHeightened (+2) The amount of damage increases by 1d6 and the amount of resistance increases by 2.","source":{"provider":"PAIZO","sourceId":"REBo9wSxDDx7Qdcc","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.capital-dividend","name":"Capital Dividend","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","wizard"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You would be reduced to 0 Hit Points but not immediately killed.\nThrough diet and other strict regimens, you've fortified your body as Kalistrade's teachings have fortified your mind. You remain at 1 Hit Point, and your skin takes on a slight warm glow.\n\nFor the next minute, any time you would regain Hit Points from a healing effect, this magic amplifies the effect, and you regain an additional 8 Hit Points.\nHeightened (+1) The additional healing increases by 2 Hit Points.","source":{"provider":"PAIZO","sourceId":"jXcsCpko8qNrWZ4x","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.captivating-adoration","name":"Captivating Adoration","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","cleric","concentrate","emotion","focus","manipulate","mental","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You become intensely entrancing, and creatures are distracted by you as long as they remain within the area. You can exclude any creatures you choose from the effects. If a creature is in the aura when you Cast the Spell or when a creature enters the area for the first time, it must attempt a Will saving throw. If a creature leaves and reenters, it uses the results of its original save.\n\nCritical Success The creature is unaffected and temporarily immune for 1 hour.\n\nSuccess The creature is with you for its next action, then is temporarily immune for 1 hour.\n\nFailure The creature is Fascinated with you.\n\nCritical Failure The creature is Fascinated with you, and its attitude toward you improves by one step.\n\nHeightened (+1) Increase the size of the emanation by 15 feet.","source":{"provider":"PAIZO","sourceId":"jJphHQlENHFlSElH","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.channel-arrogance","name":"Channel Arrogance","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"Pjbb4VnAeXokEhh0","formula":"5d10","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"Pjbb4VnAeXokEhh0":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You channel your heightened sense of self-worth into a creature, forcing them to acknowledge your true worth. You can Cast this Spell using 1 action if you know the target isn't worthy of you spending your time to generate the full force of this spell, or using 3 actions if you can't possibly hold back the majesty of your presence and must flood the target with your full attention.\n\nThe target takes 5d10 mental damage and other effects depending on its Will saving throw. If you Cast the Spell using 1 action, the target gets a result one degree of success better than it rolled.\nCritical Success The creature is unaffected.\n\nSuccess The target takes half damage and is with you for 1 round.\n\nFailure The target takes full damage and is fascinated with you for 1 round. While fascinated with you, the target must succeed at a flat when attempting to Cast a Spell or use an action with the auditory trait. On a failure, the action is disrupted as the target blurts praise for you instead of saying what it intended.\n\nCritical Failure As failure, but double damage and the effect lasts for 1 minute.\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"CVvkveEH7lonSTZd","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.chroma-leach","name":"Chroma Leach","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your hand glows with impossible colors from beyond the stars, and your touch saps both color and vitality from the living. The target must attempt a Fortitude save; creatures with the gnome trait take a –2 circumstance penalty to this save.\nCritical Success The target is unaffected.\n\nSuccess The target is Enfeebled 2 for 1 round.\n\nFailure The target is enfeebled 2 for 1 minute and Drained 1. The target is also filled with listlessness and ennui. For 1 round, if the target tries to use a move action, it must succeed at a Will save against your spell DC or the action is lost; this effect has the mental and emotion traits.\n\nCritical Failure As failure, but the creature is permanently enfeebled 2 and Drained 2 (although magic such as can remove these conditions).","source":{"provider":"PAIZO","sourceId":"4y2DMq9DV5HvmnxC","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chromatic-armor","name":"Chromatic Armor","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"2 or 3"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wrap the target in armor made of sheets of colored light. The armor sheds bright light for 20 feet (and dim light for the next 20 feet). Whenever a creature attacks the target and is adjacent to it, the attacker must attempt a Will save at the end of its action. On a failure, it becomes until the end of its next turn. Regardless of the result of the save, the attacker is temporarily immune until the end of its next turn. The dazzling effect has the light and visual traits.\n\nWhen you cast the spell, roll [[/r 2d8]]{1d8 twice} on the table below to see the armor's colors (rerolling any duplicates). Each color grants resistance 5 to the indicated damage type. If you spend three actions to Cast the Spell, roll [[/r 3d8]]{three} times instead.\n\n- Red fire\n\n- Orange acid\n\n- Yellow electricity\n\n- Green poison\n\n- Blue sonic\n\n- Indigo mental\n\n- Violet force\n\n- Matching Color The armor becomes the color matching the type of damage the target took most recently in the past minute. If it didn't take any of those seven types of damage or the armor is already that color, roll again, rerolling any results of 8.\n\nHeightened (+3) The resistance is increased by 5.","source":{"provider":"PAIZO","sourceId":"NBSBFHxBm88qxQUy","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chromatic-ray","name":"Chromatic Ray","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["attack","concentrate","light","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send out a ray of colored light streaming toward your enemy, with a magical effect depending on the ray's color. Make a spell attack roll. If you hit, roll [[/r 1d4]]{1d4} to see which beam you cast. If the ray deals damage, that damage is doubled on a critical hit. Any additional traits that apply to a ray are listed in parentheses just after the name of the color.\n\n- Red (fire) The ray deals 30[fire] damage to the target.\n\n- Orange (acid) The ray deals 40[acid] damage to the target.\n\n- Yellow (electricity) The ray deals 50[electricity] damage to the target.\n\n- Green (poison) The ray deals 25[poison] damage to the target, and the target must succeed at a Fortitude save or be Enfeebled 1 for 1 minute (Enfeebled 2 on a critical failure).\n\nHeightened (6th) The damage for 40[fire]{Red}, 50[acid]{Orange}, 60[electricity]{Yellow}, and 35[poison]{Green} each increase by 10. Roll [[/r 1d8]]{1d8} to determine the ray's color, using the results for 1-4 above and the results for 5-8 below.\n\n- Blue The ray has the effect of the spell. On a critical hit, the target is Clumsy 1 as long as it's by the flesh to stone effect.\n\n- Indigo (emotion, incapacitation, mental) The ray has the effect of the spell. On a critical hit, it has the effect of instead.\n\n- Violet The target is for 1 minute. It must also succeed at a will save or be teleported 120 feet directly away from you (if there isn't room for it to appear there, it appears in the nearest open space); this is a teleportation effect.\n\n- Intense Color The target is until the end of your next turn, or if your attack roll was a critical hit. Roll again and add the effects of another color (rerolling results of 8).","source":{"provider":"PAIZO","sourceId":"Hb8GdAhP0zBCv3zU","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cinder-swarm","name":"Cinder Swarm","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You breathe life into a mass of fiery critters. They swarm the target and create an aura around it in a . The target and enemies in the aura are subject to an effect depending on the insects you choose. On subsequent rounds, the first time you Sustain this spell each round, you repeat the effect on the target and all your enemies in the insect aura. Pick a type of insect to determine the effects.\n\n- Fire Ants You create fiery flying ants that deal 3d6 piercing damage plus 2d6 persistent fire damage with a basic Reflex save. A creature that fails its save must move 5 feet in a direction of your choice as it tries to escape the biting ants; this happens after all the creatures attempt their saves and can't add new creatures to the aura if the main target moves.\n\n- Fireflies (incapacitation) You create a flurry of fireflies that deal 3d6 fire damage and can dazzle or blind, depending on the target's Fortitude save.\n\nCritical Success The creature takes no damage.\n\nSuccess The creature takes half damage and is for 1 round.\n\nFailure The creature takes full damage and is for 1 round. It's then temporarily immune to being blinded by cinder swarm for 24 hours.\n\nCritical Failure As failure, but double damage and blinded for 1 minute.\n\nHeightened (+1) Increase the ants' piercing damage and fireflies' fire damage by 2d6.","source":{"provider":"PAIZO","sourceId":"bVvGpSOg2WaTUItS","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clairvoyance","name":"Clairvoyance","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an floating eye at a location within range (even if it's outside your line of sight or line of effect). The eye can't move, but you can see in all directions from that point as if using your normal visual senses.","source":{"provider":"PAIZO","sourceId":"zvKWclOZ7A53DObE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clinging-shadows-stance","name":"Clinging Shadows Stance","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","manipulate","monk","shadow","stance"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until you leave the stance","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You adopt the stance of clinging shadows. You can make shadow grasp Strikes. These deal 1d4 void damage; are in the brawling group; and have the agile, grapple, reach, and unarmed traits. While in clinging shadows stance, you gain a +2 circumstance bonus to Athletics checks to , and to the DC for creatures to from you.","source":{"provider":"PAIZO","sourceId":"uJXs4M6IeixfPBLc","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cloak-of-light","name":"Cloak of Light","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","healing","light","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"gftav8gvt4i3mqj6","formula":"4d6","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"gftav8gvt4i3mqj6":"2d6"}},"counteraction":false,"ritual":null,"description":"You surround yourself in holy light that restores the living and rebuffs undead. You glow with bright light in a 30-foot radius and dim light to the next 30 feet. Living creatures that begin their turn adjacent to you recover 4d6 Hit Points. Undead creatures that begin their turn adjacent to you take 4d6 vitality damage (basic Fortitude save).\nHeightened (+2) The healing increases by 2d6, and the damage to undead increases by 2d6.","source":{"provider":"PAIZO","sourceId":"ba1RyDpwq6tfW8VM","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cloud-current","name":"Cloud Current","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["air","concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Air and water vapor combine into a great cloud that funnels a powerful current within it. The eddies make the cloud appear from a distance to be a group of cloud dragons tumbling through the sky. The cloud is up to 30 feet wide, 30 feet tall, and 10 miles long. It runs parallel to the ground, and the nearest end of it must be within range and at least 100 feet above the ground. The current travels in a direction you choose when you Cast the Spell, and the travel Speed of creatures flying through the cloud in that direction is doubled. You can Dismiss the cloud.\nHeightened (6th) The duration is 8 hours, and the cloud can be up to 50 feet wide and 100 miles long.\n\nHeightened (8th) As 6th, and travel speed is quadrupled.","source":{"provider":"PAIZO","sourceId":"s7kVnr0EdljCamuR","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clownish-curse","name":"Clownish Curse","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate","mental","misfortune"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You afflict the target with a curse that causes it to emit ridiculous noises as it moves. Furthermore, the target's hands and feet become awkward and uncoordinated, as though it were wearing oversized gloves and shoes.\n\nCritical Success The target is unaffected.\n\nSuccess For 1 round, the target must roll twice and use the worse result whenever attempting an Acrobatics, Stealth, or Thievery check. If the target rolls a failure at an Acrobatics, Stealth, or Thievery check, it gets a critical failure instead.\n\nFailure As success, but the effect is 1 hour.\n\nCritical Failure As success, except the effect is permanent.","source":{"provider":"PAIZO","sourceId":"S7ylpCJyq0CYkux9","book":"Pathfinder #152: Legacy of the Lost God","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.commanding-lash","name":"Commanding Lash","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","linguistic","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1},"requirements":"Your most recent action dealt damage to a target."},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"A creature you dealt damage to on your most recent action.","area":null},"duration":{"text":"until the end of your target's next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With the threat of more pain, you compel a creature you've recently harmed. You issue a command to the target, with the effects of the spell .If the target is , , or taking persistent damage, it takes a –2 circumstance penalty to the save. Regardless of the result, the target is then temporarily immune for 1 hour","source":{"provider":"PAIZO","sourceId":"4DaHIgtMBTyxebY3","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.commune-with-corazal","name":"Commune with Corazal","kind":"RITUAL","rank":4,"rarity":"UNIQUE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"DC 24 Nature (master) or DC 29 Nature (expert)","secondaryChecks":"DC 24 Forest Lore, Perception, or Survival","secondaryCasters":3},"description":"You tap into Corazal's innumerable senses to identify disturbances throughout the Verduran Forest.\n\nCritical Success You and Corazal successfully identify a flashpoint: an imminent event that could stoke distrust and unrest. You experience a sensory premonition of the event, can cast know the way as a 7th-rank cantrip to point toward the location, and know which Elder Oak is closest to it.\n\nSuccess As success, but the ritual heavily taxes your mind and body. You are Drained 1, and until the drained condition ends, you are also Stupefied 1.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual has no effect beyond burning your mind with conflicting information. You are Drained 2, and until the drained condition ends, you are also stupefied 1 and have the Dubious Knowledge skill feat. Whenever you would decrease this drained value, the value does not decrease unless you succeed at a flat.","source":{"provider":"PAIZO","sourceId":"zIAvj7V6BTuQMAIi","book":"Pathfinder #201: Pactbreaker","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.community-repair","name":"Community Repair","kind":"RITUAL","rank":4,"rarity":"RARE","traits":["emotion"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"requirements":"rare powdered pigments in at least three different colors, worth a total of 50 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 damaged or broken public work no larger than 3,000 cubic feet (the size of a Huge creature)","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Performance (expert)","secondaryChecks":"Crafting, Performance, Society","secondaryCasters":0},"description":"You lead your community in repairing a public work, such as a bridge, well, or mural, through the power of memory and art. The primary caster serves as an emcee or leader, while each secondary caster provides a heartfelt anecdote that somehow involves the public work; for instance, recounting a story of playing at a fountain each summer. The anecdotes don't need to be firsthand accounts-a community member might sing of how their grandparents fell in love crossing a bridge every day-but they must be directly connected in some way. The GM can offer a +1 circumstance bonus to the secondary caster whose anecdote seems most moving.\n\nIf the public work was destroyed intentionally by one of the casters, the ritual automatically critically fails.\n\nCritical Success The public work is restored to its prior construction, and it takes on further qualities, encouraged by the thoughts of the community. For the next week, while a caster is within 60 feet of the site of the ritual, they receive a +1 status bonus to Will saves against emotion effects and a +10-foot status bonus to their Speeds.\n\nSuccess The public work is restored to its prior construction and function.\n\nFailure The ritual has no effect.\n\nCritical Failure The public work refuses to repair itself, and the memories of the community members are soured in response to the botched ritual. For the next week, while a caster is within 60 feet of the site of the ritual, they cannot receive any benefit from beneficial emotion effects, and they take a –10-foot status penalty to their Speeds as their movement slows to a morose crawl.","source":{"provider":"PAIZO","sourceId":"oND3oFBjxrhyVvyG","book":"Pathfinder #170: Spoken on the Song Wind","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.community-restoration","name":"Community Restoration","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","wizard"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You Cast a Spell from a wizard spell slot, and the spell affects one or more willing allies without damaging them.\nWhen you use your magic to support your allies, shared strength bolsters you all. You gain 2 temporary Hit Points per rank of the triggering spell, and can grant an equal number divided as you choose among allies affected by the triggering spell. These temporary Hit Points last for 1 minute.","source":{"provider":"PAIZO","sourceId":"6RNymgUvS87lmQOj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.compel-true-name","name":"Compel True Name","kind":"SPELL","rank":4,"rarity":"RARE","traits":["auditory","concentrate","incapacitation","linguistic","mental","true-name"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature whose true name you know","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You instruct the target to do something, compelling obedience by calling it by its true name. Your instructions can't be self-destructive. Though this spell has the linguistic trait, this applies only to the instructions; the creature doesn't need to know its own true name to be affected. The target must attempt a Will saving throw.\n\nCritical Success The target is unaffected, is temporarily immune to further castings of this spell by you for 1 week, and learns your true name.\n\nSuccess The target is unaffected, is temporarily immune to further castings of this spell by you for 1 day, and learns a fragment of your true name.\n\nFailure The target does as you command. The spell has a duration of 10 minutes, or until the target has completed a finite instruction or the instructions become selfdestructive. The creature is temporarily immune to further castings of this spell by you for 1 hour.\n\nCritical Failure As failure, but the spell's duration is 8 hours, and the creature is not temporarily immune.","source":{"provider":"PAIZO","sourceId":"53Kw9WQtvrEtABEu","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.competitive-edge","name":"Competitive Edge","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","emotion","focus","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your competitiveness drives you to prove yourself against the opposition. You gain a +1 status bonus to attack rolls and skill checks. If an enemy within 20 feet critically succeeds at an attack roll or skill check, your status bonus increases to +3 for attack rolls or that specific skill check (whichever the foe critically succeeded at) for 1 round.\n\nHeightened (7th) Increase the base bonus to +2 and the increased bonus after an enemy critically succeeds to +4.","source":{"provider":"PAIZO","sourceId":"NOB92Wpn7jXvtyVW","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.concealments-curtain","name":"Concealment's Curtain","kind":"RITUAL","rank":4,"rarity":"UNCOMMON","traits":["curse","mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"6 days"},"cost":"an ornate mirror worth at least 100 gp, naturally occurring round fruit the size and number of the target's eyes, and the same amount of flawless silver needles worth at least 1 gp each"},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"1 living creature","area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism","secondaryChecks":"Arcana, Deception, Stealth","secondaryCasters":3},"description":"At twilight for 5 days, you line the fruit in front of the mirror, chanting the name of the target, and envisioning its eyes in your mind. At exactly midnight on the last day, you drive the pins through the fruits, miming the action of methodically blinding the target to you and your companions. The target is immediately affected and can't visually detect any of the casters involved in the ritual-provided that the ritual was successful, the target is unaware of the effects. Since the ritual affects the target's ability to see the casters, rather than make the casters , effects like are ineffective against concealment's curtain; instead, the target would need to remove the curse with effects like . To perform this ritual, you must have been within 5 feet of the target at least once, close enough to get a good look at its eyes. The target is temporarily immune to further castings of concealment's curtain for 1 year.\n\nCritical Success The target is unable to visually detect the casters for the duration, and the target's detection spells don't detect the targets.\n\nSuccess The target is unable to visually detect the casters for the duration, but it's detection spells function normally.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual backfires and all casters participating in it are for the next 24 hours.\n\nHeightened (8th) You aren't satisfied with simply concealing yourself from the target. The cost of the ritual mirror increases to 1,000 gp, and a personal effect of the target is required. After completing the ritual, the target takes 6d6[mental] damage and is blinded for 1 week, requiring both a cleanse affliction and a to end the effect early. The target is aware that the ritual was cast on them; however, it doesn't have any additional information.","source":{"provider":"PAIZO","sourceId":"ehd9PtifLMwjk4ep","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.confront-selves","name":"Confront Selves","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"aCPbEUxslprwNRxh","formula":"4d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"aCPbEUxslprwNRxh":"1d6"}},"counteraction":false,"ritual":null,"description":"You show the target the spiraling web of actions and consequences that is their life and the changes wrought by these decisions upon themselves and those around them. These events swirl around the target like shards of broken pottery. When you Cast or Sustain this Spell, you force the target to confront an alternate permutation of themselves, witnessing the events of their life as if they'd chosen another path. They take 4d6 mental damage (basic Will save) and are Clumsy 1 until the beginning of your next turn. On a critical success, the spell ends.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"VGK9s6LCMMS027zP","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.confusion","name":"Confusion","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You befuddle your target with strange impulses, causing it to act randomly. The effects are determined by the target's Will save. You can Dismiss the spell.\n\nCritical Success The target is unaffected.\n\nSuccess The target babbles incoherently and is Stunned 1.\n\nFailure The target is for 1 minute. It can attempt a new save at the end of each of its turns to end the confusion.\n\nCritical Failure The target is Confused for 1 minute, with no save to end early.\n\nHeightened (8th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"LiGbewa9pO0yjbsY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.conjured-clockwork","name":"Conjured Clockwork","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"rnHUUxTIdZbVAPlh","formula":"2d8","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"rnHUUxTIdZbVAPlh":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You conjure a complex clockwork device on the ground and cause it to slowly spread across the battlefield. The area is difficult terrain. Each creature that enters or ends its turn in the area takes 2d8 slashing damage with a basic Reflex save. A creature can take this damage only once per turn. On subsequent rounds, the first time you Sustain the spell each round, you can expand the radius of the clockwork device by 5 feet.\nHeightened (+2) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"eob29LrDMH2IoeAj","book":"Pathfinder #215: To Blot Out the Sun","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.containment","name":"Containment","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wrap a creature in an immobile force field, whether to protect it or those around it. The field blocks attacks, effects, and creatures that would pass through it, including the target. The field has Hardness 10, 40 Hit Points, and immunity to critical hits and precision damage. If the target of containment is unwilling, the effects depend on the target's Reflex save.\nCritical Success The target escapes from the field as it's forming, causing it to collapse.\n\nSuccess The field partially forms with 10 Hit Points instead of 40.\n\nFailure The field has its normal effect.\nHeightened (+1) The field's Hit Points are 5 higher on a success or 15 higher on a failure.","source":{"provider":"PAIZO","sourceId":"qJQADktwD0x8kLAy","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.coral-eruption","name":"Coral Eruption","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"6d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"3d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area two 10-foot bursts that don't overlap\n\nRazor sharp coral growths erupt from the ground, transforming the landscape into a dangerous coral reef. You can create a third nonoverlapping burst if the centers of all three bursts are underwater. Creatures in the area when the spell is cast take 6d6 piercing damage and must attempt a basic Reflex save. A creature that critically fails its saving throw also takes 1d6[bleed]. The area becomes difficult terrain and hazardous terrain. A creature that moves through the area takes (floor(@item.rank/2)+1)[piercing] damage for every square of that area it moves into.\nHeightened (+2) The initial piercing damage increases by 3d6, and the hazardous terrain damage increases by 1.","source":{"provider":"PAIZO","sourceId":"h7RtKSKGViNtD5o4","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.countless-eyes","name":"Countless Eyes","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Eyes form across the touched creature's body, allowing it to see in all directions at once. The subject can't be flanked for the spell's duration. In addition, when the subject succeeds when Seeking, it critically succeeds instead.","source":{"provider":"PAIZO","sourceId":"ykyKclKTCMp2SFXa","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.creation","name":"Creation","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":0},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a temporary object from magical energy. It must consist of earthen or plant-derived matter (such as wood, paper, brick, or stone) and be 5 cubic feet or smaller. It can't rely on intricate artistry or complex moving parts, never fulfills a cost or the like, and can't be made of precious materials or materials with a rarity of uncommon or higher. It is obviously temporarily conjured, and thus can't be sold or passed off as a genuine item. The spell gains the appropriate trait for the item created, typically earth, plant, or wood.\n\nHeightened (5th) The item is metal and can include common minerals, like feldspar or quartz. The spell gains the metal trait if used to create a metal object","source":{"provider":"PAIZO","sourceId":"TUj8eugNqAvB1vVR","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.darkened-eyes","name":"Darkened Eyes","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","darkness","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You infuse a creature's vision with darkness. After attempting its save, the target becomes temporarily immune for 24 hours.\n\nCritical Success The target is unaffected.\n\nSuccess The target's darkvision or low-light vision is suppressed for 1 round.\n\nFailure As success, but the duration is 1 minute.\n\nCritical Failure As success, but the duration is 1 minute, and the target is also for the duration. It can attempt a new save at the end of each of its turns. If it succeeds, it's no longer Blinded, but its darkvision or low-light vision remains suppressed.","source":{"provider":"PAIZO","sourceId":"oiUhJbJ3YCKF62Fu","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.darkened-sight","name":"Darkened Sight","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","darkness","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You infuse a creature's vision with darkness. It receives greater darkvision, allowing it to see even in magical darkness.","source":{"provider":"PAIZO","sourceId":"2WNFbvToMsEGxmeK","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dawnflowers-light","name":"Dawnflower's Light","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","good","light","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 unattended, non-magical object of 1 Bulk or less","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The object glows with soft golden light that lays bare the truth, reveals hidden objects, and shines supernatural light on false orders. The object casts bright light in a 60-foot radius (and dim light for the next 60 feet). Within the area of bright light, Perception checks to locate hidden objects (including secret doors but not traps), Will saves to resist visual illusions, and Will saves to resist effects placed by evil creatures that inflict the controlled condition all gain a +2 status bonus. This light suppresses magical darkness of your Dawnflower's light spell's rank or lower.\n\nFinally, the supernatural light created by this spell is similar to sunlight, and while it can't damage creatures normally harmed by sunlight, it does make them uncomfortable so that they suffer a -2 status penalty to saves versus fear effects while in the area of bright light.\n\nHeightened (7th) The status bonus increases to +3.\n\nHeightened (9th) The status bonus increases to +4.","source":{"provider":"PAIZO","sourceId":"11P3KgDTMIeQIJD7","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.daydreamers-curse","name":"Daydreamer's Curse","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate","mental","misfortune"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You impose a curse upon the target that renders it easily distracted and unable to focus its thoughts on tasks that demand insight or discernment. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess For 10 minutes, the target must roll twice and use the worse result whenever attempting a Medicine, Nature, Perception, or Survival check. If the target critically succeeds at a Perception check or skill check to perform an action with the concentrate trait, the target gets a success instead.\n\nFailure As success, but the effect is permanent.\n\nCritical Failure As failure, except the target treats the outcomes of all checks with the concentrate trait as one degree of success worse than the result it rolled (a critical success becomes a success, a success becomes a failure, and a failure becomes a critical failure).","source":{"provider":"PAIZO","sourceId":"dARE6VfJ3Uoq5M53","book":"Pathfinder #164: Hands of the Devil","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.deathless-march","name":"Deathless March","kind":"SPELL","rank":4,"rarity":"RARE","traits":["auditory","concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You chant a marching song of Yled to empower the undead and terrify the living. Undead creatures within the area gain the condition for 1 minute, which they can use only to Stride.\n\nLiving creatures in the area must attempt a Will save. This gains the emotion, fear, and mental traits for living creatures.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Frightened 1.\n\nFailure The creature is Frightened 2.\n\nCritical Failure The creature is Frightened 3 and for 1 round.","source":{"provider":"PAIZO","sourceId":"ik0bjmAJse9PSECL","book":"Pathfinder Wake the Dead #4","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.debilitating-dichotomy","name":"Debilitating Dichotomy","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","cursebound","focus","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature other than you","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"9d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"3d6"}},"counteraction":false,"ritual":null,"description":"You reveal a glimpse of the impossible conflicts between the divine anathema behind your curse, forcing you to reckon with another's conflicts as well.\n\nYou and the target each take 9d6 mental damage with a basic Will save, and the target is Stunned 1 if it critically fails its save. You get a degree of success one better than you rolled for your saving throw.\n\nHeightened (+1) The damage increases by 3d6.","source":{"provider":"PAIZO","sourceId":"VmqdVWCb8zAUCW8S","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.delusional-pride","name":"Delusional Pride","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","emotion","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You make the target overconfident, leading it to ascribe failure to external factors. The target attempts a Will save to determine the spell's duration and is temporarily immune for 24 hours regardless of the save's result.\n\nCritical Success The target is unaffected.\n\nSuccess The duration is 1 round. If the target fails at an attack roll or skill check, it takes a –1 status penalty to attack rolls and skill checks until the end of its turn (or the end of its next turn, if it attempted the roll outside its turn). If the creature fails a second time while taking this penalty, the penalty increases to –2.\n\nFailure As success, but the duration is 10 minutes.\n\nCritical Failure As success, but the duration is 24 hours.","source":{"provider":"PAIZO","sourceId":"J8pL8yTshga8QOk8","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.destructive-aura","name":"Destructive Aura","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Swirling sands of divine devastation surround you, weakening the defenses of all they touch. Reduce the resistances of yourself and creatures in the area by 2.\n\nHeightened (+2) Reduce the resistances by an additional 2.","source":{"provider":"PAIZO","sourceId":"7d4DUTDIlzDa8OvX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.detect-creator","name":"Detect Creator","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","detection","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"target":"1 destroyed undead","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You examine the remains or spiritual residue of a destroyed undead creature to locate that undead's creator, perhaps a necromancer or vampire. If the creator is within range, you can sense the direction to them. If the creator is within 100 feet, you sense their presence within 100 feet, and the spell ends; you can't further home in on their location. If there's lead or running water between you and the undead's creator, this spell can't locate them. This spell fails automatically if the undead doesn't have a specific creator or the specific creator isn't on the same plane.","source":{"provider":"PAIZO","sourceId":"kREpsv78anJpIiq2","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.detect-scrying","name":"Detect Scrying","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","detection","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"By reading trace auras, you detect the presence of scrying effects in the area. If detect scrying is higher rank than a scrying effect, you gain a glimpse of the scrying creature and learn its approximate distance and direction.\n\nHeightened (6th) The duration is until the next time you make your daily preparations.","source":{"provider":"PAIZO","sourceId":"AnWCohzPgK4L9GVl","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.diamond-dust","name":"Diamond Dust","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","cleric","cold","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15,"text":"15-foot emanation centered on you"}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"2d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You supercool the nearby air, forming a cloud of dancing ice crystals in an emanation around you. A creature other than you that enters the area or ends its turn within the area takes 2d6 cold damage. A creature can take this damage only once per turn. The crystals scatter and refract light; if a light effect enters diamond dust's area, any creatures targeted by that effect gain a +2 status bonus to AC and saves against it. While the spell persists, you can activate or deactivate this aura by Sustaining the spell. You can Dismiss this spell.\nHeightened (+2) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"wjJW9hWY5CkkMvY5","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dimensional-steps","name":"Dimensional Steps","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","manipulate","teleportation","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":20},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You teleport to a location up to 20 feet away within your line of sight.\n\nHeightened (+1) The distance you can teleport increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"zjG6NncHyAKqSF7m","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dinosaur-form","name":"Dinosaur Form","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel the primal forces of nature to transform into a Large animal battle form, specifically that of a powerful and terrifying dinosaur. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal, but this has no effect on the form's Size or statistics. While in this form, you gain the animal and dinosaur traits. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n\n- AC = 18 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 15 temporary Hit Points.\n\n- Low-light vision and imprecise scent 30 feet.\n\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +16, and your damage bonus is +9. These attacks are Strength based (for the purpose of the condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n\n- Athletics modifier of +18, unless your own is higher.\n\nYou also gain specific abilities based on the form you choose:\n\n- Ankylosaurus\n\n- Speed 25 feet;\n\n- Melee 1 tail (backswing, reach 10 feet), Damage 2d6 bludgeoning;\n\n- Melee 1 foot, Damage 2d6 bludgeoning.\n\n- Brontosaurus\n\n- Speed 25 feet;\n\n- Melee 1 tail (reach 15 feet), Damage 2d6 bludgeoning;\n\n- Melee 1 foot, Damage 2d8 bludgeoning.\n\n- Deinonychus\n\n- Speed 40 feet;\n\n- Melee 1 talon (agile), Damage 2d4 piercing plus 1 persistent bleed;\n\n- Melee 1 jaws, Damage 1d10 piercing.\n\n- Stegosaurus\n\n- Speed 30 feet;\n\n- Melee 1 tail (reach 10 feet), Damage 2d8 piercing.\n\n- Triceratops\n\n- Speed 30 feet;\n\n- Melee 1 horn, Damage 2d8 piercing, plus 1d6 persistent bleed on a critical hit;\n\n- Melee 1 foot, Damage 2d6 bludgeoning.\n\n- Tyrannosaurus\n\n- Speed 30 feet;\n\n- Melee 1 jaws (deadly d12, reach 10 feet), Damage 1d12 piercing;\n\n- Melee 1 tail (reach 10 feet), Damage 1d10 bludgeoning.\n\nHeightened (5th) Your battle form is Huge and your attacks have 15-foot reach, or 20-foot reach if they started with 15-foot reach. You instead gain 20 temporary HP, an attack modifier of +18, a damage bonus of +6, double the damage dice, and Athletics +21.\n\nHeightened (7th) Your battle form is Gargantuan and your attacks have 20-foot reach, or 25-foot reach if they started with 15-foot reach. You instead gain AC = 21 + your level, 25 temporary HP, an attack modifier of +25, a damage bonus of +15, double the damage dice, and Athletics +25.","source":{"provider":"PAIZO","sourceId":"KhM8MhoUgoUjBMIz","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dirge-of-remembrance","name":"Dirge of Remembrance","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","sonic"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"pX92NmS2GoYpHJrp","formula":"4d10","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"pX92NmS2GoYpHJrp":"1d10"}},"counteraction":false,"ritual":null,"description":"You sing a funereal dirge to force restless spirits to fully manifest in the Material Plane. Each incorporeal creature in the area takes 4d10 sonic damage (this damage bypasses its resistances) depending on the result of its Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and becomes semi-corporeal until the spell ends. All attacks against it get the benefit of a ghost touch rune.\n\nCritical Failure As failure, but double damage.\n\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"FCfd1zUrqPaLEtau","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.discern-lies","name":"Discern Lies","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental","revelation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Falsehoods ring in your ears like discordant notes. You gain a +4 status bonus to Perception checks when someone Lies.","source":{"provider":"PAIZO","sourceId":"uNsliWpl8Q1JdFcM","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dispelling-globe","name":"Dispelling Globe","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":10}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You create an immobile globe around yourself that attempts to counteract any spell from outside the globe whose area or targets enter into the globe, as if the globe were a spell 1 rank lower than its actual spell rank.\n\nIf the counteract attempt succeeds, it prevents only the portion of the spell that would have entered the globe (so if the spell also has targets outside the globe, or part of its area is beyond the globe, those targets or that area is affected normally).\n\nYou must form the sphere in an unbroken open space, so its edges don't pass through any creatures or objects, or the spell is lost (though creatures can enter the globe after the spell is cast).","source":{"provider":"PAIZO","sourceId":"JOdOpbPDl7nqvJUm","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.disperse-into-air","name":"Disperse into Air","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["air","cleric","focus","manipulate","polymorph"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You take damage from an enemy or a hazard.\n\nAfter taking the triggering damage, you transform into air. Until the end of the current turn, you can't be attacked or targeted, you don't take up space, you can't act, and any auras or emanations you have are suppressed. At the end of the turn, you re-form in any space you can occupy within 15 feet of where you were when you dispersed. Any auras or emanations you had are restored as long as their duration didn't run out while you were dispersed.","source":{"provider":"PAIZO","sourceId":"L8pzCOi7Jzx5ALs9","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divine-keystone","name":"Divine Keystone","kind":"RITUAL","rank":4,"rarity":"RARE","traits":["consecration","holy"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 days"},"cost":"holy water, powdered silver, and purified chalk worth 200 gp","requirements":"cornerstone from the structure of the casting area used as a locus"},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":100}},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{},"areaFeet":20},"counteraction":false,"ritual":{"primaryCheck":"Arcana (master) or Religion (expert)","secondaryChecks":"Architecture Lore, Crafting, or Engineering Lore","secondaryCasters":1},"description":"You magically remove and consecrate the cornerstone of a building or ruin in the center of a settlement before returning the stone to its structure to spread its divine protection into the settlement around it. Once the final hammer strike returns the stone to its structure, the area protected by the sanctified stone becomes a sacred space, protecting the living from undead. Within the protected area, the consecrated site is holy, undead creatures can't be created or raised, and living creatures are to the undead.\n\nA successful used on a specific effect removes only that effect (such as the invisibility effect). However, destroying or removing the keystone ends the entire ritual and all its effects.\nCritical Success You create the effects described above, and the keystone's consecration effect doubles its radius.\n\nSuccess You create the effects described above.\n\nFailure The ritual has no effect.\n\nCritical Failure The area becomes a font of power for undead for the next month. All undead creatures in the ritual's area gain fast healing 3 and resistance 3 to holy.\n\nHeightened (+1) The emanation protected by the keystone increases by 20 feet.","source":{"provider":"PAIZO","sourceId":"xKHq2Eisapixvj6q","book":"Pathfinder Adventure Path: Hellbreakers","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divine-wrath","name":"Divine Wrath","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","sanctified","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"4d10","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You channel the fury of divinity against your foes. You deal 4d10 spirit damage to enemies in the area, depending on their Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is Sickened 1.\n\nCritical Failure The creature takes full damage and is Sickened 2; while it's sickened, it's also Slowed 1.\n\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"hVU9msO9yGkxKZ3J","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.door-to-beyond","name":"Door to Beyond","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":5},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"qeAvRsIUYQwyitMP","formula":"4d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"qeAvRsIUYQwyitMP":"1d6"}},"counteraction":false,"ritual":null,"description":"Striking at thin air, you create hairline cracks in an unoccupied adjacent space that lead somewhere outside reality. Air rushes through the cracks, drawing Large or smaller creatures and objects of light Bulk or less toward the center. Large or smaller creatures in the area must attempt a Fortitude save at the start of their turn; creatures that move into the area must attempt the save upon entering.\n\nThe cracks of the door to beyond are too thin for anything to fully slip through, but decompressive effects deal 4d6 slashing damage to any creature or object that ends its turn adjacent to the door. You are unaffected by your own door to beyond. You can Dismiss the spell.\n\nSuccess The creature is unaffected.\n\nFailure The creature is pulled 10 feet toward the door.\n\nCritical Failure The creature is pulled 20 feet toward the door.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"iMmexY6ZosLS4I5R","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.downpour","name":"Downpour","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","water"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth a torrential downpour, which extinguishes non-magical flames. Creatures in the area are and gain fire resistance 10. Creatures outside the area are Concealed to those inside the area. If a creature with weakness to water ends its turn in the area, the downpour triggers its weakness.\n\nHeightened (+1) The fire resistance increases by 2.","source":{"provider":"PAIZO","sourceId":"K4LXpaBWrGy6jIER","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.draw-the-lightning","name":"Draw the Lightning","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","electricity","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature that is either taller than you or higher than you","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":4,"damage":{"0":"4d12"}},"counteraction":false,"ritual":null,"description":"Calling out to the skies, you summon a bolt of lightning to strike through a foe above you and down into your weapon or your body, charging it with electrical power. You must hold your weapon or an empty hand aloft as part of this spell's somatic component. When you do, a bolt of lightning descends from a storm cloud in the air above your and through the target, dealing 3d12 electricity damage with a basic Reflex save. For the rest of the spell's duration, your first Strike each round with the weapon you held aloft (or with your unarmed attacks if you held an empty hand aloft) deals an additional 1d12 electricity damage.\n\nThe spell creates its own storm cloud if necessary, so you can cast draw the lightning anywhere, even underground. If draw the lightning is cast outside under a cloudy or stormy sky, increase the bolt's damage by 2d12[electricity].\n\nHeightened (8th) The damage dealt to the initial target increases by 4d12, and the additional damage dealt on the first Strike each turn increases by 1d12.","source":{"provider":"PAIZO","sourceId":"n7OgbKme4hNwxVwQ","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dreamers-call","name":"Dreamer's Call","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","illusion","incapacitation","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"until the end of the target's next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a vivid, illusory daydream drawn from the images of the target's dreams. The daydream appears in an unoccupied space in range, and you attempt to draw the target toward it.\n\nCritical Success The target is unaffected.\n\nSuccess The target's attention wavers. It becomes by the daydream.\n\nFailure The target is fascinated with the daydream and pursues a course of action you choose as its first action after you Cast the Spell: approach the daydream, run away from it (as the condition), Release what it's holding as an offering, or Drop Prone in obeisance.\n\nCritical Failure As failure, but the target follows the course of action for as many actions as possible for the spell's duration, and does nothing else.","source":{"provider":"PAIZO","sourceId":"PztLrElcZfLwRnEq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dull-ambition","name":"Dull Ambition","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","curse","manipulate","mental","misfortune"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You curse the target to fail in all avenues of its life that require drive and ambition, as it inadvertently undermines its own goals at every turn. The effect is based on the target's Will save.\nCritical Success The target is unaffected.\n\nSuccess For 1 hour, the target rolls twice and uses the lower result on initiative rolls.\n\nFailure For 1 day, the target rolls twice and uses the lower result on initiative rolls and any check to determine the success of a downtime activity.\n\nCritical Failure As failure, but the duration is unlimited.","source":{"provider":"PAIZO","sourceId":"MLdMUOdwSKegOGlo","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dust-storm","name":"Dust Storm","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["air","cleric","concentrate","focus","manipulate","nonlethal"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20,"text":"20-foot-radius burst"}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You call forth a swirling storm of dust. The dust storm obscures vision, with the effect of . The dust also makes the air unbreathable; creatures in the area must hold their breath, though wearing a scarf or similar clothing over the mouth increases the time the creature can hold its breath to 5 rounds. Creatures entering or starting their turn in the dust storm take 1d6 slashing damage. Creatures that have the water trait or that are made primarily of liquid take double damage.\n\nHeightened (+2) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"K1wmI4qPmRhFczmy","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dutiful-challenge","name":"Dutiful Challenge","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"As you challenge an enemy, you take some of its attention away from your allies. The target takes a -1 status penalty to attack rolls, damage rolls, and skill checks against creatures other than you, and you take a -1 status penalty to attack rolls, damage rolls, and skill checks against creatures other than the target.\n\nEach time a creature other than you uses a hostile action that affects the challenged enemy, the enemy can attempt a Will save. On a success, the enemy no longer takes the penalty against that creature. You can Dismiss the spell, and it ends automatically if you or the target is defeated.\n\nHeightened (+3) The status penalties increase by 1.","source":{"provider":"PAIZO","sourceId":"caehfpQz7yp9yNzz","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ectoplasmic-interstice","name":"Ectoplasmic Interstice","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You force the mortal Universe and Ethereal Planes to partially merge, creating a zone that causes incorporeal and spiritual entities to take on many of the aspects of corporeal creatures. Within the area of effect, incorporeal creatures can't pass through solid objects or corporeal creatures, and they can manipulate and attempt Strength-based checks against physical creatures and objects. An incorporeal PC or other creature with a normal Strength modifier simply uses that modifier, but if the creature had a Strength modifier of –5, like most incorporeal monsters, it uses a +4 modifier instead, increasing its Athletics modifier by 9 accordingly. Attacks against creatures that are within the area overcome resistances as if they were by ghost touch weapons.","source":{"provider":"PAIZO","sourceId":"QE9f3OxvvBThymD4","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-gift","name":"Elemental Gift","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"An elemental force fills your target, granting the target the swiftness of air, the ruggedness of earth, the sting of fire, or the flexibility of water, depending on which element you choose. Choose an element when you Cast the Spell. The target gains the benefit of that element as described below, and this spell gains that trait's element.\n\n- Air The target gains a +30-foot status bonus to its land Speed and gains a fly Speed equal to its land Speed without the status bonus.\n\n- Earth While on the ground, the target gets a +2 status bonus to Fortitude and Reflex saves against effects that would or it, and to saves against effects that would attempt to knock it . In addition, the ground adjacent to the target is difficult terrain, and the difficult terrain moves with the target, though the target ignores this difficult terrain with its own movement.\n\n- Fire The target's melee unarmed Strikes and melee weapon Strikes deal 1d6 persistent fire damage on a hit.\n\n- Metal The target's Strikes using a metal weapon or an unarmed attack deal an additional 1d4 electricity damage on a hit and get a +1 status bonus to the attack roll if the target is made of metal or wearing metal armor.\n\n- Water The target takes on a watery sheen, gaining resistance 5 to fire and a swim Speed equal to its land Speed.\n\n- Wood The target gains a number of temporary Hit Points equal to the spell's rank, then gains half that number of temporary HP at the start of each of its turns.\n\nHeightened (8th) You can target up to 5 willing creatures.","source":{"provider":"PAIZO","sourceId":"e36Z2t6tLdW3RUzZ","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-sense","name":"Elemental Sense","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","revelation"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The elements grant you sensory enhancements. Choose one of the options below. The spell gains the listed trait or traits.\n\n- Aquatic Echolocation (water) You use your hearing as a precise sense when underwater.\n\n- Heatsense (fire) You can sense creatures with a temperature of 90º Fahrenheit or higher within 30 feet as an imprecise sense.\n\n- Magnetoreception (metal) You can sense creatures carrying metal items with a total of 1 Bulk or greater; this is an imprecise sense with a range of 30 feet. If a creature is made of metal or has the metal trait, you can detect it as though magnetoreception were a precise sense. In addition, you continuously know which direction is north.\n\n- Mechanoreception (air) You can see creatures and objects. They appear to you as translucent shapes, and they are to you.\n\n- Tremorsense(earth) You gain tremorsense (imprecise) with a range of 30 feet.\n\n- Woodsense(plant, wood) You can sense creatures carrying wood items with a total of 1 Bulk or greater; this is an imprecise sense with a range of 30 feet. If a creature is made of wood or has the plant or wood trait, you can detect it as though woodsense were a precise sense.\n\nHeightened (6th) The duration increases to 8 hours, and you can take 1 minute to recalibrate the sense, switching from your current elemental sense to a different one.","source":{"provider":"PAIZO","sourceId":"wfqBbQ2RXj4VjKUZ","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-sheath","name":"Elemental Sheath","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You coat yourself in nature's power. Choose air, earth, fire, metal, water, or wood; the spell gains that trait. You become completely covered by armor formed from that element, gaining a +1 circumstance bonus to AC and resistance 5 to two types of damage based on the element you choose.\n\nAir bludgeoning and electricity\n\nEarth bludgeoning and poison\n\nFire fire and slashing\n\nMetal acid and slashing\n\nWater cold and piercing\n\nWood piercing and void.\nHeightened (+2) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"WkqamCF8r4O5Gh0n","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-tempest","name":"Elemental Tempest","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","spellshape","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your spellcasting surrounds you in a storm of elemental energy.\n\nIf the next action you take is to Cast a Spell from your wizard spell slots that's an evocation spell dealing acid, cold, electricity, or fire damage, a 10-foot emanation of energy surrounds you as you cast the spell.\n\nFoes in the area take 1d6 damage per spell rank of the spell you just cast of the same damage type the spell deals (choose one if it deals multiple types). Combine the damage from both elemental tempest and the other spell against foes who take damage from both before applying bonuses, penalties, resistance, weakness, and the like.","source":{"provider":"PAIZO","sourceId":"vfHr1N8Rf2bBpdgn","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.elephant-form","name":"Elephant Form","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel the primal forces of nature to transform into a Large battle form, specifically that of a powerful and terrifying elephant or similar creature, such as a mammoth, mastodon, or anancus. This spell has the effects of , except you gain the following specific abilities instead of the form-specific abilities of dinosaur form.\n\n- Speed 40 feet;\n\n- Melee 1 foot, Damage 2d8 bludgeoning.\n\n- Melee 1 trunk (reach 10 feet), Effect grabbing trunk;\n\n- Melee 1 tusk (reach 10 feet), Damage 2d6 piercing.\n\nGrabbing Trunk A creature up to two sizes smaller that's hit by your trunk is . If you succeed at your check against a creature grabbed by your trunk, you can reposition the creature to another space within your trunk's reach.\n\nHeightened (5th) Your elephant form is Huge; your trunk and tusk attacks have 15-foot reach, and your foot attack has 10-foot reach. You instead gain 20 temporary HP, an attack modifier of +18, a damage bonus of +6, double the damage dice, and Athletics +21.\n\nHeightened (7th) Your elephant form is Gargantuan; your trunk and tusk attacks have 20-foot reach, and your foot attack has 15-foot reach. Your AC is 21 + your level and you instead gain 25 temporary HP, an attack modifier of +25, a damage bonus of +15, double the damage dice, and Athletics +25.","source":{"provider":"PAIZO","sourceId":"zjYQyuBNT5VjV4mz","book":"Pathfinder #177: Burning Tundra","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enduring-might","name":"Enduring Might","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An attack or effect would deal damage to you.\n\nYour own might mingles with divine power to protect you from harm. You gain resistance equal to 8 plus your Strength modifier against all damage from the triggering attack or effect.\n\nHeightened (+1) The resistance increases by 2.","source":{"provider":"PAIZO","sourceId":"eG1fBodYwolaXK98","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.energy-absorption","name":"Energy Absorption","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","wizard"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An effect would deal acid, cold, electricity, or fire damage to you\n\nYou're used to mitigating the damage done by bombs, siege engines, and magical artillery. You gain resistance 15 to your choice of acid, cold, electricity, or fire damage from the triggering effect. The resistance applies only to the triggering effect's initial damage.\n\nHeightened (+1) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"LoBjvguamA12iyW0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enervation","name":"Enervation","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Extending a finger, you fire a beam of void energy that weakens the life force of any creature it touches. Each living creature in the line must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes (floor(@item.rank/2))d8[persistent,void] damage.\n\nFailure The creature takes (floor(@item.rank/2)*2)d8[persistent,void] damage and becomes Drained 1.\n\nCritical Failure The creature takes (floor(@item.rank/2)*2)d8[persistent,void] damage and becomes Drained 2 and Doomed 1.\nHeightened (+2) The persistent void damage increases by 1d8 on a success, or by 2d8 on a failure or critical failure.","source":{"provider":"PAIZO","sourceId":"eexkxcqnkXazsGfK","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enhance-senses","name":"Enhance Senses","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{}},"counteraction":false,"ritual":null,"description":"You enhance the target's senses. The target gains low-light vision, and all of the target's imprecise senses have their distances doubled. If the target already has low-light vision, they gain darkvision.\n\nHeightened (+2) The number of targets increases by 1.","source":{"provider":"PAIZO","sourceId":"a5uwCgOe7ayHPtHe","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entangle-fate","name":"Entangle Fate","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"2 to 4 creatures in range","area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause a swirl of energy to entangle the fates of all caught within the blast. Each creature in the area must attempt a Will save.\nCritical Success The creature is unaffected.\n\nSuccess The creature's fate becomes distorted, and momentary conflicting glimpses of the immediate future cause the creature to become until the start of its next turn.\n\nFailure As success, but the creature is off-guard for the duration of the spell. If more than one of the targets failed to resist this spell, the creature also becomes Stupefied 1 for the duration of the spell as its fate and those of the other creatures continue to clash and strain against each other.\n\nCritical Failure As failure, but any creature that becomes stupefied 1 for the duration of the spell also becomes Enfeebled 1 and Clumsy 1 for the spell's duration.","source":{"provider":"PAIZO","sourceId":"11haL5O9KMpY5Fv7","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ephemeral-hazards","name":"Ephemeral Hazards","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","illusion","manipulate","mental","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"SQUARE","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"4d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"Area (continued) four 10-foot-by-10-foot spaces\nYou create illusory hazards, such as spinning blades or a puddle of acid, in four 10-foot-by–10-foot spaces within range. The hazards are merely a mental projection, and a creature receives a Will save each time it touches a hazard or is occupying one's space at the start of its turn. Depending on the result, the creature takes 4d6 mental damage and might have difficulty moving through the area. A creature can take this damage only once per turn, even if it moves through several hazards. Choose bludgeoning, slashing, piercing, acid, cold, electricity, fire, or sonic damage when you Cast ephemeral hazards; resistances and weaknesses to those damage types apply if the target thinks they do, as judged by the GM. You can freely choose the appearance and damage type of each hazard as long as its appearance reflects the type of damage it deals (for instance, a hazard that deals piercing damage might take the form of sharpened spikes).\nCritical Success The creature is unaffected by the hazards and no longer needs to attempt Will saves against them.\n\nSuccess The creature realizes the hazards aren't real but still takes half damage from them; on future Will saves against the hazards, the creature continues to use this result unless it rolls a critical success.\n\nFailure The target takes full damage and treats the square as difficult terrain.\n\nCritical Failure The target takes double damage and can't pass through a square containing a hazard.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"HisaZTk67YAxLGBq","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.eradicate-undeath","name":"Eradicate Undeath","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"4d12","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d12"}},"counteraction":false,"ritual":null,"description":"A massive deluge of life energy causes the undead to fall apart. Each undead creature in the area takes 4d12 vitality damage.\n\nHeightened (+1) The damage increases by 1d12.","source":{"provider":"PAIZO","sourceId":"J5MNC4xq3CHH31qT","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.euphoric-renewal","name":"Euphoric Renewal","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You view death not as an ending but a beginning, and you delight in dancing on its edge. Each time you gain the dying condition and then regain consciousness while under the effect of euphoric renewal, you gain three benefits.\n\n- You're on your next turn. You can use the extra action only to Stand.\n\n- You gain a +1 circumstance bonus to saves for 1 minute.\n\n- You gain 8 temporary Hit Points that last for 1 minute.\n\nHeightened (+1) The number of temporary HP increases by 2.","source":{"provider":"PAIZO","sourceId":"mTpPZIJ2sdgusPP1","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.extract-brain","name":"Extract Brain","kind":"RITUAL","rank":4,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"fine surgical tools and rare preservative salts and fluids worth a total value of 100 gp"},"targeting":{"range":{"kind":"TOUCH"},"target":"1 Large or smaller creature or corpse","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryChecks":"Medicine","secondaryCasters":0},"description":"You perform a complex magical operation on a willing or creature or a corpse, delicately cutting into the skull and removing the creature's brain without damaging the organ. If you have an empty brain cylinder on hand, you can place the extracted brain into the brain cylinder as part of this ritual (this includes preparing the brain cylinder for use, such as removing a previous brain and filling the cylinder with the preservative fluids required to make it function).\n\nOr at the GM's discretion, if you have a nearly completed carrion golem at hand, you can place the extracted brain into the golem. The body of a living creature subjected to this ritual dies, regardless of the ritual's result, as does the extracted brain if it is not placed into a golem or cylinder (or otherwise preserved) within 3 rounds.\n\nCritical Success The ritual succeeds on a living creature, or on a corpse that has been dead no longer than 8 hours before the ritual began. If you place the brain into a golem, the golem retains the brain's memories, along with its mental ability scores, alignment, and related skills.\n\nSuccess The ritual succeeds on a living creature or on a corpse that has been dead no longer than 1 hour before the ritual began.\n\nFailure The ritual fails and the brain dies.\n\nCritical Failure The ritual seems to succeed but warps the brain unrecognizably into a hostile entity, potentially allowing an alien intelligence to seep into it.\n\nHeightened (8th) You can place the extracted brain into an inactive flesh golem on a critical success.\n\nHeightened (9th) You can place the extracted brain into an inactive alchemical golem on a critical success.","source":{"provider":"PAIZO","sourceId":"hdzyDrRdHSse88XM","book":"Pathfinder Adventure: Malevolence","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fallen-soldiers-lament","name":"Fallen Soldier's Lament","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","illusion","manipulate","mental","visual"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"1 corpse of a Medium or smaller creature that has died within the past 8 hours","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You raise an illusion in the space of a fallen foe, crafting it to resemble a ghost of your target before parading it across the battlefield. Whenever you Cast this Spell or Sustain this spell, you move the illusion up to 30 feet and cause each enemy in a 30-foot emanation of the spirit to attempt a Will save against your spell DC. Enemies who fail become Frightened 1 (or Frightened 2 on a critical failure).\nHeightened (6th) You can target a corpse of any size that has died within the past 8 hours.","source":{"provider":"PAIZO","sourceId":"LjLSvAqnR03EnITX","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fallow-field","name":"Fallow Field","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","void"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A sickly yellow light fills the area as entropic forces prevent healing. When a creature within the area would regain Hit Points, such as from a healing effect or an ability like fast healing or regeneration, it must attempt a Will save.\nCritical Success The creature regains the full number of Hit Points that would be restored by the healing effect and is temporarily immune for 1 minute.\n\nSuccess The creature regains the full number of Hit Points that would be restored.\n\nFailure The creature regains only half the number of Hit Points that would be restored.\n\nCritical Failure The creature doesn't regain Hit Points from the healing effect.","source":{"provider":"PAIZO","sourceId":"2RhZkHNv8ajq0yLq","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.false-nature","name":"False Nature","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"one unattended item or one item you're holding","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an illusion that makes an object seem to be something entirely different. When you Cast this Spell, speak aloud a declarative statement that the target is a different, nonspecific object. Your statement can't presuppose any other facts. For instance, you could claim an object is \"a stone\" or \"an antidote,\" but not \"the Starstone\" or \"the antidote to the lethal poison you already drank.\" Creatures who previously observed the target receive an immediate Will save to disbelieve, but on a failure, the illusion temporarily rewrites their memory that the object was something different. A creature who failed their Will save, or didn't already see the item's original form, must Interact with the illusion as normal to receive a Perception check against the spell DC to disbelieve. When the spell ends, targets remember the object's true nature, even if they never disbelieved the spell.","source":{"provider":"PAIZO","sourceId":"5z1700cfG8Ybm0e6","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.familiar-form","name":"Familiar Form","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform into a Tiny animal that commonly serves as a spellcaster's familiar. You gain the effects of the spell pest form, heightened to the level of familiar form you cast. However, you can transform into only a bat, cat, raven, snake, or other Tiny animal of a type that you have seen serve as a spellcaster's familiar.\n\nWhile in this form, despite the restrictions from polymorph battle forms, you retain the ability to cast spells of 1st rank or lower but only those without material components. You still can't make any Strikes or other attacks in pest form, as normal.\n\nHeightened (6th) You retain the ability to cast spells of 2nd rank or lower, rather than 1st, but still only those without material components. Additionally, the duration of familiar form increases to 10 minutes.\n\nHeightened (8th) You retain the ability to cast spells of 3rd rank or lower, rather than 1st, but still only those without material components. Additionally, the duration of familiar form increases to 10 minutes.","source":{"provider":"PAIZO","sourceId":"CHZQJg7O7991Vl4m","book":"Pathfinder Lost Omens Pathfinder Society Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.favorable-review","name":"Favorable Review","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You enchant a creature to ensure they have only good things to say about your show. Identify a single creature, location, or performance, such as \"Dame Ellendia,\" \"Savories Meats,\" or \"the Theater of the Mind's latest magic show.\" The target must attempt Will save. You can Dismiss the spell.\n\nCritical Success The target is unaffected and knows you tried to trick it.\n\nSuccess The target is unaffected but thinks your spell was something harmless instead of favorable review, unless it identifies the spell (usually using ).\n\nFailure The target cannot speak unfavorably about the subject for 1 week. This doesn't change the target's opinion about the subject, but the target's attempts to speak ill of the subject-whether in speech, writing, or other communication-always twist into compliments and praise instead. The target likely becomes aware of this effect quickly and can avoid speaking about the subject entirely if they choose.\n\nCritical Failure As failure, except the duration is permanent and the target genuinely holds a favorable opinion about the subject, with their attitude toward the creature (or creatures associated with the subject, such as the owner of a location or artists in a performance) becoming two degrees better (for example, instead of ).\n\nHeightened (8th) The range increases to 60 feet and you can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"i7u6gAdNcyIyyo3h","book":"Pathfinder #152: Legacy of the Lost God","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fearful-feast","name":"Fearful Feast","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","fear","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"6d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"Trigger A creature within range becomes\nYou open your mouth wide and inhale sharply; you draw in the bravery, self-confidence, and hope to which the frightened target clings and then strip away the target's false assumption that these fragile emotions can save them from the oblivion of terror. You deal 6d4 mental damage to the creature, which must attempt a Will saving throw.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage; you regain Hit Points equal to half the damage the target takes.\n\nCritical Failure The creature's frightened condition increases by 1 (to a maximum of Frightened 4) and it takes double damage; you regain Hit Points equal to half the damage the target takes.\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"0qA4MfMkFklOz2Lk","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fey-form","name":"Fey Form","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Channeling the mischievous fey, you transform into a fey battle form, which is Medium unless stated otherwise. When you cast this spell, choose dryad, elananx, naiad, redcap, or unicorn. If you choose unicorn, the battle form is Large and you must have space to expand or the spell is lost. While in this form, you gain the fey trait. Unless you choose elananx or unicorn, you have hands in this battle form and can use manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of the form that you choose:\n- AC = 19 + your level. Ignore your armor's check penalty and Speed reduction.\n- 15 temporary Hit Points and weakness 5 to cold iron.\n- Low-light vision.\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +16, and you use the listed damage. These attacks are Dexterity based. If your attack modifier is higher for the given unarmed attack or weapon, you can use it instead.\n- Acrobatics modifiers of +16, unless your own modifier is higher.\nYou also gain specific abilities based on the type of fey:\n- Dryad The temporary HP gained increases to 30; Speed 25 feet; weakness 5 to fire\n- Size Medium\n- Melee 1 branch, Damage 1d12+8 bludgeoning.\n\n- Elananx Speed 30 feet; resistance 5 to fire\n- Size Medium\n- Melee 1 jaws, Damage 1d6+8 piercing plus 1d6 fire;\n- Melee 1 claw (agile), Damage 1d6+8 slashing.\n\n- Naiad Speed 25 feet, swim 25 feet; resistance 5 to fire\n- Size Medium\n- Melee 1 aqueous fist (water), Damage 1d8+8 bludgeoning.\n\n- Redcap Speed 40 feet;\n- Size Small;\n- Melee 1 scythe (deadly d10, trip), Damage 1d10+8 slashing;\n- Melee 1 boot (agile, versatile B), Damage 1d6+8 piercing.\n\n- Unicorn gain the beast trait in addition to fey; Speed 40 feet; resistance 5 to poison;\n- Size Large;\n- Melee 1 horn, Damage 1d10+8 piercing plus 1 spirit;\n- Melee 1 hoof (agile), Damage 1d8+8 bludgeoning; all Strikes have the effects of a property rune.","source":{"provider":"PAIZO","sourceId":"Qu4IThrk1wpONwjT","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.filter-air","name":"Filter Air","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","concentrate","manipulate","subtle"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You're exposed to a poison or disease that has the inhaled trait, and you're aware of the exposure\n\nRequirements You breathe air.\nYou suck in a rough breath of air, and your body automatically filters out the harmful molecules that would infest your lungs. As you breathe for the duration of the spell, you get the outcome one degree of success higher on your saving throws against inhaled poisons and diseases.","source":{"provider":"PAIZO","sourceId":"GgrrcKQgJH2Eykq1","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fire-shield","name":"Fire Shield","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You create a hovering shield made of fire. As long as the shield persists, its heat grants you cold resistance 5 and makes you immune to mild and severe environmental cold. You can Raise a Shield with the fire shield as a normal shield to gain a +1 circumstance bonus to AC. You can use the Shield Block reaction with the fire shield, which has Hardness 10, is immune to fire, and has 40 HP (with no Broken Threshold), and its Hardness is halved against effects that have the water trait. If you Shield Block a melee attack that is either an unarmed attack or made by an adjacent attacker, the attacker takes 2d6 fire damage.\n\nHeightened (+2) The cold resistance increases by 5, the HP increase by 10, and the fire damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"YrzBLPLd3r9m6t1p","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.flame-barrier","name":"Flame Barrier","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the creature that would take fire damage","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An effect would deal fire damage to either you or an ally within range.\n\nYou swiftly deflect incoming flames. The target gains fire resistance 15 against the triggering effect.\n\nHeightened (+2) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"y7Tusv3CieZktkkV","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.flicker","name":"Flicker","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You flicker quickly between your current plane and another. You gain resistance 5 to all damage, except force. At the end of each of your turns, you automatically teleport 10 feet in a random direction, as determined by the GM. You can Sustain the spell to teleport in this way.\n\nHeightened (+2) The resistance increases by 3.","source":{"provider":"PAIZO","sourceId":"zR67Rt3UMHKC5evy","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fly","name":"Fly","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target can soar through the air, gaining a fly Speed equal to its Speed or 20 feet, whichever is greater.\n\nHeightened (7th) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"A2JfEKe6BZcTG1S8","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.font-of-serenity","name":"Font of Serenity","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","emotion","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"A divine beacon radiates serenity, soothing nearby allies.\n\nAllies within the area gain a +1 status bonus to saving throws against emotion effects.\n\nAn ally can touch the font at the center of the burst as an Interact action; if they do so, the spell attempts to counteract one emotion effect affecting the ally of the ally's choice, after which that emotion effect is temporarily immune for 1 day. If the spell succeeds at the counteract check, it removes the emotion effect from your ally, though not from any other creatures the effect might be affecting.\nHeightened (+4) The bonus increases by 1.","source":{"provider":"PAIZO","sourceId":"yY1H5zhO5dHmD8lz","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.forgotten-lines","name":"Forgotten Lines","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 text or remnants thereof","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Members of the Lacunafex and other allies use this spell to restore material that Thrune agents have redacted from historical or otherwise valuable texts. You learn one piece of information that was removed from the target text after its creation. You can instead learn one piece of information from a text that had been destroyed, but you must have a fragment of the text, such as a piece of the cover, a page, or even a clasp or metal fittings.\n\nHeightened (6th) The spell reconstructs all missing information regarding a specific topic of your choice.\n\nHeightened (9th) The spell also reveals information the writer self-censored and didn't commit to paper.","source":{"provider":"PAIZO","sourceId":"u0AtDZs6BhBPtjEs","book":"Pathfinder #147: Tomorrow Must Burn","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
